            @lru_cache(None)
            def dp(i, sm, tight):
                if sm > max_sum:
                    return 0
                if i == n:
                    return 1 if sm >= min_sum else 0
                lim = int(s[i]) if tight else 9
                res = 0
                for d in range(lim + 1):
                    res += dp(i + 1, sm + d, tight and d == lim)
                return res % MOD

            return dp(0, 0, True)

        ds = sum(int(c) for c in num1)
        extra = 1 if min_sum <= ds <= max_sum else 0
        return (f(num2) - f(num1) + extra) % MOD
