            for end in range(pos, len(s)):
                val = val * 10 + int(s[end])
                if val > target:
                    break
                if can(s, end + 1, target - val):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            if can(str(i * i), 0, i):
                total += i * i
        return total
