class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)
        INF = float('inf')
        divs = [[] for _ in range(n + 1)]
        for L in range(2, n + 1):
            for d in range(1, L):
                if L % d == 0:
                    divs[L].append(d)
        cost = [[INF] * (n + 1) for _ in range(n + 1)]
        for i in range(n):
            for j in range(i + 2, n + 1):
                L = j - i
                best = INF
                for d in divs[L]:
                    tot = 0
                    for r in range(d):
                        t = s[i + r:j:d]
                        tot += sum(a != b for a, b in zip(t, reversed(t)))
                        if tot // 2 >= best:
                            break
                    tot //= 2
                    if tot < best:
                        best = tot
                cost[i][j] = best
        prev = [INF] * (n + 1)
        prev[0] = 0
        for c in range(1, k + 1):
            cur = [INF] * (n + 1)
            for j in range(2 * c, n + 1):
                b = INF
                for i in range(2 * (c - 1), j - 1):
                    if prev[i] != INF:
                        v = prev[i] + cost[i][j]
                        if v < b:
                            b = v
                cur[j] = b
            prev = cur
        return prev[n]
