- If the number has started, the new digit must differ from `prev` by exactly 1.
- At the end, count the path only if `started` is true, so 0 is excluded.

The string length is at most 100, so the state space is small and memoized recursion is fast enough.

```python
from functools import lru_cache

class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def count(s):
            n = len(s)

            @lru_cache(maxsize=None)
            def dp(pos, prev, tight, started):
                if pos == n:
                    return 1 if started else 0
                lim = int(s[pos]) if tight else 9
                res = 0
                for d in range(lim + 1):
                    nt = tight and d == lim
                    if not started:
                        if d == 0:
                            res += dp(pos + 1, -1, nt, False)
                        else:
                            res += dp(pos + 1, d, nt, True)
                    else:
                        if abs(d - prev) == 1:
                            res += dp(pos + 1, d, nt, True)
                return res % MOD

            r = dp(0, -1, True, False)
            dp.cache_clear()
            return r

        def is_step(s):
            for i in range(1, len(s)):
                if abs(int(s[i]) - int(s[i - 1])) != 1:
                    return False
            return True

        ans = count(high) - count(low) + (1 if is_step(low) else 0)
        return ans % MOD
```

