class Solution:
    def countPairs(self, coordinates: List[List[int]], k: int) -> int:
        cnt = defaultdict(int)
        res = 0
        SH = 21
        pairs = [(a, k - a) for a in range(k + 1)]
        for x, y in coordinates:
            for a, b in pairs:
                key = ((x ^ a) << SH) | (y ^ b)
                if key in cnt:
                    res += cnt[key]
            cnt[(x << SH) | y] += 1
        return res

