class Solution:
    def maxSum(self, nums: List[int], m: int, k: int) -> int:
        cnt = defaultdict(int)
        s = 0
        best = 0
        for i, x in enumerate(nums):
            cnt[x] += 1
            s += x
            if i >= k:
                y = nums[i - k]
                cnt[y] -= 1
                if cnt[y] == 0:
                    del cnt[y]
                s -= y
            if i >= k - 1 and len(cnt) >= m:
