class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        S = t + '#' + s + s[:-1]
        L = len(S)
        z = [0] * L
        l = r = 0
        for i in range(1, L):
            if i < r:
                zi = min(r - i, z[i - l])
            else:
                zi = 0
            while i + zi < L and S[zi] == S[i + zi]:
                zi += 1
            z[i] = zi
            if i + zi > r:
                l, r = i, i + zi
        cnt = 0
        c0 = 0
        base = n + 1
        for i in range(n):
            if z[base + i] >= n:
                cnt += 1
                if i == 0:
                    c0 = 1
        if cnt == 0:
            return 0
        inv = pow(n, MOD - 2, MOD)
        pk = pow(n - 1, k, MOD)
        sign = 1 if k % 2 == 0 else MOD - 1
        f = (pk + (n - 1) * sign) % MOD * inv % MOD
        g = (pk - sign) % MOD * inv % MOD
        return (c0 * f + (cnt - c0) * g) % MOD

class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # KMP failure function on t
        pi = [0] * n
        j = 0
        for i in range(1, n):
            while j and t[i] != t[j]:
                j = pi[j - 1]
            if t[i] == t[j]:
                j += 1
            pi[i] = j
        text = s + s[:-1]
        matches = []
        j = 0
        for i, ch in enumerate(text):
            while j and ch != t[j]:
                j = pi[j - 1]
            if ch == t[j]:
                j += 1
            if j == n:
                matches.append(i - n + 1)
                j = pi[j - 1]
        c = len(matches)
        if c == 0:
            return 0
        sign = 1 if k % 2 == 0 else MOD - 1
        inv_n = pow(n, MOD - 2, MOD)
        f1 = (pow(n - 1, k, MOD) - sign) % MOD * inv_n % MOD
        f0 = (f1 + sign) % MOD
        if matches[0] == 0:
            return (f0 + (c - 1) * f1) % MOD
        return c * f1 % MOD

class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        st = t + '#' + s + s[:-1]
        m = len(st)
        z = [0] * m
        l = r = 0
        for i in range(1, m):
            if i < r:
                zi = z[i - l]
                if zi > r - i:
                    zi = r - i
            else:
                zi = 0
            while i + zi < m and st[zi] == st[i + zi]:
                zi += 1
            z[i] = zi
            if i + zi > r:
                l, r = i, i + zi
        zero_ok = False
        cnt = 0
        base = n + 1
        for i in range(n):
            if z[base + i] >= n:
                if i == 0:
                    zero_ok = True
                else:
                    cnt += 1
        p = pow(n - 1, k, MOD)
        sign = 1 if k % 2 == 0 else MOD - 1
        inv = pow(n, MOD - 2, MOD)
        f0 = (p + (n - 1) * sign) % MOD * inv % MOD
        f1 = (p - sign) % MOD * inv % MOD
        ans = cnt * f1 % MOD
        if zero_ok:
            ans = (ans + f0) % MOD
        return ans

class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # find match positions of t in s+s[:-1]
        p = t + '#' + s + s[:-1]
        m = len(p)
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j and p[i] != p[j]:
                j = pi[j - 1]
            if p[i] == p[j]:
                j += 1
            pi[i] = j
        cnt0 = 0
        cnt_other = 0
        # position in s+s[:-1] start index = i - 2n
        for i in range(2 * n, m):
            if pi[i] == n:
                start = i - 2 * n
                if start == 0:
                    cnt0 += 1
                else:
                    cnt_other += 1
        if cnt0 == 0 and cnt_other == 0:
            return 0
        inv_n = pow(n, MOD - 2, MOD)
        a = pow(n - 1, k, MOD)
        sign = 1 if k % 2 == 0 else MOD - 1
        f0 = (a + (n - 1) * sign) % MOD * inv_n % MOD
        f1 = (a - sign) % MOD * inv_n % MOD
        return (cnt0 * f0 + cnt_other * f1) % MOD

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1
        cnt = [0] * 64
        for x in nums:
            cnt[x.bit_length() - 1] += 1
        ans = 0
        i = 0
        while i < 62:
            if (target >> i) & 1:
                if cnt[i] > 0:
                    cnt[i] -= 1
                else:
                    j = i + 1
                    while j < 63 and cnt[j] == 0:
                        j += 1
                    if j >= 63:
                        return -1
                    ans += j - i
                    cnt[j] -= 1
                    for k in range(i, j):
                        cnt[k] += 1
                    # the extra 2^i piece is used for this bit
            cnt[i + 1] += cnt[i] // 2
            i += 1
        return ans

