class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1
        cnt = [0] * 64
        for x in nums:
            cnt[x.bit_length() - 1] += 1
        acc = 0
        ops = 0
        for i in range(62):
            acc += cnt[i] << i
            if (target >> i) & 1:
                if acc >= (1 << i):
                    acc -= (1 << i)
                else:
                    j = i + 1
                    while cnt[j] == 0:
                        j += 1
                    ops += j - i
                    cnt[j] -= 1
                    for k in range(i + 1, j):
                        cnt[k] += 1
                    acc += (1 << i)
        return ops

class Solution:
    def minimumPossibleSum(self, n: int, target: int) -> int:
        MOD = 10**9 + 7
        m = target // 2
        if n <= m:
            return (n * (n + 1) // 2) % MOD
        k = n - m
        total = m * (m + 1) // 2 + k * target + k * (k - 1) // 2
        return total % MOD

class Solution:
    def constructProductMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        MOD = 12345
        n, m = len(grid), len(grid[0])
        res = [[0] * m for _ in range(n)]
        pre = 1
        for i in range(n):
            row = grid[i]
            rr = res[i]
            for j in range(m):
                rr[j] = pre
                pre = pre * row[j] % MOD
        suf = 1
        for i in range(n - 1, -1, -1):
            row = grid[i]
            rr = res[i]
            for j in range(m - 1, -1, -1):
                rr[j] = rr[j] * suf % MOD
                suf = suf * row[j] % MOD
        return res

