class Solution:
    def getMaxFunctionValue(self, receiver: List[int], k: int) -> int:
        n = len(receiver)
        nxt = np.array(receiver, dtype=np.int64)
        s = nxt.copy()
        cur = np.arange(n, dtype=np.int64)
        total = np.arange(n, dtype=np.int64)
        while k:
