    def minLengthAfterRemovals(self, nums: List[int]) -> int:
        n = len(nums)
        m = 0
        cnt = 0
        for i in range(n):
            if i > 0 and nums[i] == nums[i-1]:
                cnt += 1
            else:
                cnt = 1
            if cnt > m:
                m = cnt
        return max(2 * m - n, n % 2)
