class Solution:
    def countSubMultisets(self, nums: List[int], l: int, r: int) -> int:
        MOD = 10**9 + 7
        cnt = Counter(nums)
        zeros = cnt.pop(0, 0)
        dp = [0] * (r + 1)
        dp[0] = 1
        for x, c in cnt.items():
            if x > r:
                continue
            pre = dp[:]
            for s in range(x, r + 1):
                pre[s] += pre[s - x]
            k = (c + 1) * x
            if k <= r:
                new = pre[:k] + [a - b for a, b in zip(pre[k:], pre[:r + 1 - k])]
            else:
                new = pre
            dp = [v % MOD for v in new]
        return sum(dp[l:r + 1]) * (zeros + 1) % MOD

