        n = len(nums)
        total = sum(nums)
        q, r = divmod(target, total)
        if r == 0:
            return q * n
        arr = nums + nums
        best = float('inf')
        left = 0
        s = 0
        for right in range(len(arr)):
            s += arr[right]
            while s > r and left <= right:
                s -= arr[left]
