class Solution:
    def canMakePalindromeQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        m = n // 2
        A = s[:m]
        B = s[m:][::-1]
        def build(t):
            pre = [[0] * (m + 1) for _ in range(26)]
            for ch in range(26):
                c = chr(97 + ch)
                p = pre[ch]
                acc = 0
                for i in range(m):
                    if t[i] == c:
                        acc += 1
                    p[i + 1] = acc
            return pre
        PA = build(A)
        PB = build(B)
        mis = [0] * (m + 1)
        for i in range(m):
            mis[i + 1] = mis[i] + (A[i] != B[i])

        def mcount(l, r):
            if l > r:
                return 0
            return mis[r + 1] - mis[l]

        def cnt(P, l, r):
            if l > r:
                return [0] * 26
            return [P[ch][r + 1] - P[ch][l] for ch in range(26)]

        res = []
        for a, b, c, d in queries:
            c2, d2 = n - 1 - d, n - 1 - c
            if a <= c2:
                P1, P2 = PA, PB
                x1, y1, x2, y2 = a, b, c2, d2
            else:
                P1, P2 = PB, PA
                x1, y1, x2, y2 = c2, d2, a, b
            if mcount(0, x1 - 1) or mcount(max(y1, y2) + 1, m - 1):
                res.append(False)
                continue
            if y2 <= y1:
                res.append(cnt(P1, x1, y1) == cnt(P2, x1, y1))
            elif y1 < x2:
                ok = (mcount(y1 + 1, x2 - 1) == 0
                      and cnt(P1, x1, y1) == cnt(P2, x1, y1)
                      and cnt(P1, x2, y2) == cnt(P2, x2, y2))
                res.append(ok)
            else:
                c1 = cnt(P1, x1, y1)
                f2 = cnt(P2, x1, x2 - 1)
                c2v = cnt(P2, x2, y2)
                f1 = cnt(P1, y1 + 1, y2)
                ok = True
                for ch in range(26):
                    l1 = c1[ch] - f2[ch]
                    l2 = c2v[ch] - f1[ch]
                    if l1 < 0 or l2 < 0 or l1 != l2:
                        ok = False
                        break
                res.append(ok)
        return res

