            D[i + 1] = D[i] + (A[i] != B[i])

        def diff(l, r):
            if l > r:
                return 0
            return D[r + 1] - D[l]

        def check(PX, PY, a, b, c, d):
            # a <= c; X's interval [a,b], Y's interval [c,d]
            if diff(0, a - 1) > 0:
                return False
            if diff(max(b, d) + 1, m - 1) > 0:
                return False
            if d <= b:
                for ch in range(26):
                    if PX[ch][b + 1] - PX[ch][a] != PY[ch][b + 1] - PY[ch][a]:
                        return False
                return True
            if c > b:
                if diff(b + 1, c - 1) > 0:
                    return False
                for ch in range(26):
                    px = PX[ch]; py = PY[ch]
                    if px[b + 1] - px[a] != py[b + 1] - py[a]:
                        return False
                    if px[d + 1] - px[c] != py[d + 1] - py[c]:
                        return False
                return True
            # overlap c <= b < d
            for ch in range(26):
                px = PX[ch]; py = PY[ch]
                if px[b + 1] - px[a] < py[c] - py[a]:
                    return False
                if py[d + 1] - py[c] < px[d + 1] - px[b + 1]:
                    return False
                if px[d + 1] - px[a] != py[d + 1] - py[a]:
                    return False
            return True

        res = []
        for a, b, c, d in queries:
            c2 = n - 1 - d
            d2 = n - 1 - c
            if a <= c2:
                res.append(check(PA, PB, a, b, c2, d2))
            else:
                res.append(check(PB, PA, c2, d2, a, b))
        return res

