class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        m = 1
        x = k
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                m *= p ** ((e + 1) // 2)
            p += 1
        if x > 1:
            m *= x
        L = 2 * m
        cnt = {(0, 0): 1}
        bal = 0
        res = 0
        vowels = set('aeiou')
        for j, c in enumerate(s, 1):
            bal += 1 if c in vowels else -1
            key = (j % L, bal)
            res += cnt.get(key, 0)
            cnt[key] = cnt.get(key, 0) + 1
        return res

