class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        arr = [ord(c) - 97 for c in word]
        res = 0
        start = 0
        segments = []
        for i in range(1, n + 1):
            if i == n or abs(arr[i] - arr[i - 1]) > 2:
                segments.append((start, i))
                start = i
        for s, e in segments:
            L = e - s
            for m in range(1, 27):
                w = m * k
                if w > L:
                    break
                cnt = [0] * 26
                good = 0
                for i in range(s, e):
                    c = arr[i]
                    if cnt[c] == k:
                        good -= 1
                    cnt[c] += 1
                    if cnt[c] == k:
                        good += 1
                    if i - s >= w:
                        d = arr[i - w]
                        if cnt[d] == k:
                            good -= 1
                        cnt[d] -= 1
                        if cnt[d] == k:
                            good += 1
                    if i - s >= w - 1 and good == m:
                        res += 1
        return res
```

