class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        nums.sort()
        m = nums[len(nums) // 2]
        s = str(m)
        L = len(s)
        cands = set()
        cands.add(10 ** (L - 1) - 1)
        cands.add(10 ** L + 1)
        half = (L + 1) // 2
        p = int(s[:half])
        for q in (p - 1, p, p + 1):
            if q <= 0:
                continue
            qs = str(q)
            if L % 2 == 0:
                pal = qs + qs[::-1]
            else:
                pal = qs + qs[:-1][::-1]
            cands.add(int(pal))
        # also include small single digits safety
        for d in range(1, 10):
            cands.add(d)
        best = None
        for c in cands:
            if c <= 0 or c >= 10 ** 9:
                continue
            cs = str(c)
            if cs != cs[::-1]:
                continue
            cost = sum(abs(a - c) for a in nums)
            if best is None or cost < best:
                best = cost
        return best

