class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        n = len(s)
        a = [ord(ch) - 97 for ch in s]
        # order[p]: list of (pos, char) sorted by next occurrence in s[p:]
        order = [None] * (n + 1)
        cur = []
        order[n] = []
        for p in range(n - 1, -1, -1):
            c = a[p]
            cur = [(p, c)] + [x for x in cur if x[1] != c]
            order[p] = cur

        def find(p, mask):
            need = k - bin(mask).count('1')
            for pos, ch in order[p]:
                if not (mask >> ch) & 1:
                    if need == 0:
                        return pos
                    need -= 1
            return n

        P = [0] * (n + 1)
        for j in range(n - 1, -1, -1):
            e = find(j + 1, 1 << a[j])
            P[j] = 1 + P[e]

        best = P[0]
        L = 0
        M = 0
        for i in range(n):
            cnt = bin(M).count('1')
            for c in range(26):
                b = 1 << c
                if not (M & b) and cnt == k:
                    j = find(i + 1, b)
                    val = L + 2 + P[j]
                else:
                    j = find(i + 1, M | b)
                    val = L + 1 + P[j]
                if val > best:
                    best = val
            # advance greedy with original char
            b = 1 << a[i]
            if not (M & b) and cnt == k:
                L += 1
                M = b
            else:
                M |= b
        return best

