    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        n = len(s)
        a = [ord(ch) - 97 for ch in s]
        order = [None] * (n + 2)
        order[n] = []
        order[n + 1] = []
        for p in range(n - 1, -1, -1):
            c = a[p]
            lst = [(p, c)]
            for x in order[p + 1]:
                if x[1] != c:
                    lst.append(x)
            order[p] = lst

        def end(p, S, cnt):
            if p >= n:
                return n
            for pos, ch in order[p]:
                b = 1 << ch
                if not (S & b):
                    cnt += 1
                    if cnt > k:
                        return pos
                    S |= b
            return n

        suf = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suf[i] = 1 + suf[end(i, 0, 0)]

        ans = suf[0]
        pre = 0
        mask = 0
        cnt = 0
        for i in range(n):
            for c in range(26):
                b = 1 << c
                if not (mask & b) and cnt == k:
                    e = end(i + 1, b, 1)
                    val = pre + 2 + suf[e]
                else:
                    S = mask | b
                    cc = cnt + (0 if mask & b else 1)
                    e = end(i + 1, S, cc)
                    val = pre + 1 + suf[e]
                if val > ans:
                    ans = val
            b = 1 << a[i]
            if not (mask & b):
                if cnt == k:
                    pre += 1
                    mask = b
                    cnt = 1
                else:
                    mask |= b
                    cnt += 1
        return ans

