from typing import List
from collections import Counter

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        INF = float('inf')
        d = [[INF]*26 for _ in range(26)]
        for i in range(26):
            d[i][i] = 0
        for o, c, w in zip(original, changed, cost):
            a, b = ord(o)-97, ord(c)-97
            if w < d[a][b]:
                d[a][b] = w
        for k in range(26):
            dk = d[k]
            for i in range(26):
                di = d[i]
                dik = di[k]
                if dik == INF:
                    continue
                for j in range(26):
                    v = dik + dk[j]
                    if v < di[j]:
                        di[j] = v
        total = 0
        for (s, t), cnt in Counter(zip(source, target)).items():
            if s == t:
                continue
            v = d[ord(s)-97][ord(t)-97]
            if v == INF:
                return -1
            total += v * cnt
        return total
