    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        m = len(s)
        def count(N):
            t = str(N)
            n = len(t)
            if n < m:
                return 0
            p = n - m
            res = 0
            for i in range(p):
                d = int(t[i])
                rem = p - 1 - i
                if d > limit:
                    res += (limit + 1) * (limit + 1) ** rem
                    return res
                res += d * (limit + 1) ** rem
            if s <= t[p:]:
                res += 1
            return res
        return count(finish) - count(start - 1)

