            t = str(N)
            n, m = len(t), len(s)
            if n < m:
                return 0
            res = 0
            k = n - m
            for i in range(k):
                d = int(t[i])
                res += min(d, limit + 1) * (limit + 1) ** (k - i - 1)
                if d > limit:
                    return res
            if int(s) <= int(t[k:]):
