class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def count(N):
            if N < 1:
                return 0
            t = str(N)
            if len(t) < len(s):
                return 0
            k = len(t) - len(s)
            res = 0
            for i in range(k):
                d = int(t[i])
                res += min(d, limit + 1) * (limit + 1) ** (k - i - 1)
                if d > limit:
                    return res
            if t[k:] >= s:
                res += 1
            return res
        return count(finish) - count(start - 1)

