    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        best = {}
        pre = 0
        ans = None
        for x in nums:
            # pre is prefix sum before x
            if x in best:
                if pre < best[x]:
                    best[x] = pre
            else:
                best[x] = pre
            pre += x
            for t in (x - k, x + k):
                if t in best:
                    cand = pre - best[t]
                    if ans is None or cand > ans:
                        ans = cand
        return ans if ans is not None else 0
