class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n, m = len(nums), len(changeIndices)

        def ok(t):
            last = [-1] * n
            for s in range(t):
                last[changeIndices[s] - 1] = s
            if any(x == -1 for x in last):
                return False
            free = 0
            for s in range(t):
                i = changeIndices[s] - 1
                if last[i] == s:
                    if free < nums[i]:
                        return False
                    free -= nums[i]
                else:
                    free += 1
            return True

        lo, hi = 1, m
        if not ok(m):
            return -1
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
