class Solution:
    def medianOfUniquenessArray(self, nums: List[int]) -> int:
        n = len(nums)
        total = n * (n + 1) // 2
        target = (total + 1) // 2
        mx = max(nums) + 1

        def enough(k):
            cnt = [0] * mx
            distinct = 0
            left = 0
            res = 0
            for right in range(n):
                v = nums[right]
                if cnt[v] == 0:
                    distinct += 1
                cnt[v] += 1
                while distinct > k:
                    u = nums[left]
                    cnt[u] -= 1
                    if cnt[u] == 0:
                        distinct -= 1
                    left += 1
                res += right - left + 1
                if res >= target:
                    return True
            return res >= target

        lo, hi = 1, len(set(nums))
        while lo < hi:
            mid = (lo + hi) // 2
            if enough(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

