class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n, m = len(nums), len(andValues)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for j in range(m):
            t = andValues[j]
            ndp = [INF] * (n + 1)
            vals = []  # AND values, ordered by increasing l
            bests = []
            for r in range(n):
                x = nums[r]
                nv = []
                nb = []
                for k in range(len(vals)):
                    v = vals[k] & x
                    b = bests[k]
                    if nv and nv[-1] == v:
                        if b < nb[-1]:
                            nb[-1] = b
                    else:
                        nv.append(v)
                        nb.append(b)
                b = dp[r]
                if nv and nv[-1] == x:
                    if b < nb[-1]:
                        nb[-1] = b
                else:
                    nv.append(x)
                    nb.append(b)
                vals, bests = nv, nb
                for k in range(len(vals)):
                    if vals[k] == t:
                        if bests[k] < INF:
                            ndp[r + 1] = bests[k] + x
                        break
            dp = ndp
        return dp[n] if dp[n] < INF else -1

