class Solution:
    def findProductsOfElements(self, queries: List[List[int]]) -> List[int]:
        def stats(n):
            # numbers 0..n-1: total set bits, total sum of bit positions
            c = 0
            s = 0
            i = 0
            while (1 << i) <= n:
                full = (n >> (i + 1)) << i
                rem = (n & ((1 << (i + 1)) - 1)) - (1 << i)
                if rem > 0:
                    full += rem
                c += full
                s += full * i
                i += 1
            return c, s

        def cnt(n):
            c = 0
            i = 0
            while (1 << i) <= n:
                full = (n >> (i + 1)) << i
                rem = (n & ((1 << (i + 1)) - 1)) - (1 << i)
                if rem > 0:
                    full += rem
                c += full
                i += 1
            return c

        def F(k):
            if k <= 0:
                return 0
            lo, hi = 1, 1 << 51
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cnt(mid) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            n = lo
            c, s = stats(n)
            r = k - c
            b = 0
            while r > 0:
                if (n >> b) & 1:
                    s += b
                    r -= 1
                b += 1
            return s

        ans = []
        for fr, to, m in queries:
            e = F(to + 1) - F(fr)
            ans.append(pow(2, e, m))
        return ans

