class Solution:
    def findProductsOfElements(self, queries: List[List[int]]) -> List[int]:
        def cnt_and_sexp(n):
            c = 0
            s = 0
            for j in range(51):
                p = 1 << j
                if p > n:
                    break
                k = ((n >> (j + 1)) << j) + max(0, (n & ((p << 1) - 1)) - p)
                c += k
                s += k * j
            return c, s

        def cnt(n):
            c = 0
            for j in range(51):
                p = 1 << j
                if p > n:
                    break
                c += ((n >> (j + 1)) << j) + max(0, (n & ((p << 1) - 1)) - p)
            return c

        def f(k):
            # sum of exponents of first k elements
            if k <= 0:
                return 0
            lo, hi = 0, 1 << 50
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cnt(mid) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            n = lo
            c, s = cnt_and_sexp(n)
            r = k - c
            j = 0
            while r > 0:
                if (n >> j) & 1:
                    s += j
                    r -= 1
                j += 1
            return s

        res = []
        for a, b, m in queries:
            e = f(b + 1) - f(a)
            res.append(pow(2, e, m) % m)
        return res

