class Solution:
    def minimumDiameterAfterMerge(self, edges1: List[List[int]], edges2: List[List[int]]) -> int:
        def diameter(edges):
            n = len(edges) + 1
            adj = [[] for _ in range(n)]
            for a, b in edges:
                adj[a].append(b)
                adj[b].append(a)
            def bfs(s):
                dist = [-1] * n
                dist[s] = 0
                q = deque([s])
                last = s
                while q:
                    u = q.popleft()
                    last = u
                    for v in adj[u]:
                        if dist[v] < 0:
                            dist[v] = dist[u] + 1
                            q.append(v)
                return last, dist[last]
            far, _ = bfs(0)
