class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        best = defaultdict(lambda: [0] * (k + 1))
        glob = [0] * (k + 1)
        for v in nums:
            b = best[v]
            new = [0] * (k + 1)
            for j in range(k + 1):
                val = b[j] + 1
                if j > 0:
                    val = max(val, glob[j - 1] + 1)
                new[j] = max(val, 1)
            for j in range(k + 1):
