class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        start.sort()
        def ok(x):
            prev = start[0]
            for s in start[1:]:
                cur = max(s, prev + x)
                if cur > s + d:
                    return False
                prev = cur
            return True
        lo, hi = 0, (start[-1] + d - start[0]) // (len(start) - 1) + 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

