        start.sort()
        n = len(start)

        def ok(g):
            prev = start[0]
            for i in range(1, n):
                s = start[i]
                cur = prev + g
                if cur < s:
                    cur = s
                if cur > s + d:
                    return False
                prev = cur
            return True

        lo, hi = 0, (start[-1] + d - start[0]) // (n - 1) + 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

