class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        adj = [[i + 1] if i < n - 1 else [] for i in range(n)]
        dist = list(range(n))
        res = []
        for u, v in queries:
            adj[u].append(v)
            if dist[u] + 1 < dist[v]:
                dist[v] = dist[u] + 1
                for w in range(v, n):
                    dw = dist[w] + 1
                    for x in adj[w]:
                        if dw < dist[x]:
                            dist[x] = dw
            res.append(dist[n - 1])
        return res

