class Solution:
    def timeTaken(self, edges: List[List[int]]) -> List[int]:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        w = [1 if i % 2 else 2 for i in range(n)]
        parent = [-1] * n
        order = [0]
        seen = [False] * n
        seen[0] = True
        for u in order:
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    parent[v] = u
                    order.append(v)
        d1 = [0] * n
        d2 = [0] * n
        bc = [-1] * n
        for u in reversed(order):
            p = parent[u]
            if p >= 0:
                val = d1[u] + w[u]
                if val > d1[p]:
                    d2[p] = d1[p]
                    d1[p] = val
                    bc[p] = u
                elif val > d2[p]:
                    d2[p] = val
        up = [0] * n
        for u in order:
            p = parent[u]
            if p >= 0:
                other = d2[p] if bc[p] == u else d1[p]
                up[u] = w[p] + max(up[p], other)
        return [max(d1[i], up[i]) for i in range(n)]

