class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        dp = [1] * (nums[0] + 1)
        for i in range(1, len(nums)):
            prev = nums[i-1]
            pre = [0] * (prev + 2)
            for a in range(prev + 1):
                pre[a+1] = (pre[a] + dp[a]) % MOD
            d = max(0, nums[i] - prev)
            ndp = [0] * (nums[i] + 1)
            for b in range(nums[i] + 1):
                hi = b - d
                if hi < 0:
                    continue
                hi = min(hi, prev)
                ndp[b] = pre[hi+1]
            dp = ndp
        return sum(dp) % MOD

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        dp = [1] * (nums[0] + 1)
        for i in range(1, len(nums)):
            d = max(0, nums[i] - nums[i-1])
            pre = []
            s = 0
            for x in dp:
                s = (s + x) % MOD
                pre.append(s)
            m = len(pre)
            new = [0] * (nums[i] + 1)
            for v in range(nums[i] + 1):
                k = v - d
                if k >= 0:
                    new[v] = pre[min(k, m - 1)]
            dp = new
        return sum(dp) % MOD

