    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        dp = [1] * (nums[0] + 1)
        for i in range(1, len(nums)):
            prev = nums[i-1]
            pre = []
            s = 0
            for x in dp:
                s = (s + x) % MOD
                pre.append(s)
            d = max(0, nums[i] - prev)
            ndp = [0] * (nums[i] + 1)
            for v in range(nums[i] + 1):
                idx = min(v - d, prev)
                if idx >= 0:
                    ndp[v] = pre[idx]
            dp = ndp
        return sum(dp) % MOD

