class Solution:
    def reportSpam(self, message: List[str], bannedWords: List[str]) -> bool:
        banned = set(bannedWords)
        cnt = 0
        for w in message:
            if w in banned:
                cnt += 1
                if cnt >= 2:
                    return True
        return False
