from math import factorial

class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        half = (n + 1) // 2
        seen = set()
        for p in range(10 ** (half - 1), 10 ** half):
            s = str(p)
            if n % 2 == 0:
                full = s + s[::-1]
            else:
                full = s + s[-2::-1]
            if int(full) % k == 0:
                seen.add(''.join(sorted(full)))
        fact = [factorial(i) for i in range(n + 1)]
        res = 0
        for t in seen:
            cnt = [0] * 10
            for ch in t:
                cnt[ord(ch) - 48] += 1
            denom = 1
            for c in cnt:
                denom *= fact[c]
            total = fact[n] // denom
            if cnt[0] > 0:
                d2 = 1
                for i, c in enumerate(cnt):
                    if i == 0:
                        d2 *= fact[c - 1]
                    else:
                        d2 *= fact[c]
                total -= fact[n - 1] // d2
            res += total
        return res

