class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m, n = len(board), len(board[0])
        cand = []
        for i in range(m):
            row = sorted(((board[i][j], i, j) for j in range(n)), reverse=True)[:3]
            cand.extend(row)
        bycol = {}
        for v, i, j in cand:
            bycol.setdefault(j, []).append((v, i, j))
        cand2 = []
        for j, lst in bycol.items():
            lst.sort(reverse=True)
            cand2.extend(lst[:3])
        cand2.sort(reverse=True)
        cand2 = cand2[:15]
        best = None
        for a, b, c in combinations(cand2, 3):
            if a[1] != b[1] and a[1] != c[1] and b[1] != c[1] and \
               a[2] != b[2] and a[2] != c[2] and b[2] != c[2]:
                s = a[0] + b[0] + c[0]
                if best is None or s > best:
                    best = s
        return best

