from typing import List

class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])
        INF = float('inf')
        dist = [[INF] * n for _ in range(m)]
        dist[0][0] = grid[0][0]
        dq = deque([(0, 0)])
        while dq:
            i, j = dq.popleft()
            d = dist[i][j]
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                x, y = i + di, j + dj
                if 0 <= x < m and 0 <= y < n:
                    nd = d + grid[x][y]
                    if nd < dist[x][y]:
                        dist[x][y] = nd
                        if grid[x][y] == 0:
                            dq.appendleft((x, y))
                        else:
                            dq.append((x, y))
        return health - dist[m-1][n-1] >= 1

