from collections import deque

class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        n = len(positions)
        pts = [tuple(p) for p in positions] + [(kx, ky)]
        moves = [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]

        def bfs(sx, sy):
            dist = [[-1]*50 for _ in range(50)]
            dist[sx][sy] = 0
            q = deque([(sx, sy)])
            while q:
                x, y = q.popleft()
                dd = dist[x][y] + 1
                for dx, dy in moves:
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < 50 and 0 <= ny < 50 and dist[nx][ny] < 0:
                        dist[nx][ny] = dd
                        q.append((nx, ny))
            return dist

        d = []
        for (sx, sy) in pts:
            dist = bfs(sx, sy)
            d.append([dist[pts[j][0]][pts[j][1]] for j in range(n)])

        full = (1 << n) - 1
        dp = [None] * (1 << n)
        dp[0] = [0] * (n + 1)
        for mask in range(1, 1 << n):
            bits = [j for j in range(n) if mask >> j & 1]
            alice = (n - len(bits)) % 2 == 0
            vals = [(j, dp[mask ^ (1 << j)][j]) for j in bits]
            row = [0] * (n + 1)
            if mask == full:
                cand = [n]
            else:
                cand = [i for i in range(n) if not (mask >> i & 1)]
            for i in cand:
                di = d[i]
                if alice:
                    best = -1
                    for j, v in vals:
                        t = di[j] + v
                        if t > best:
                            best = t
                else:
                    best = 1 << 30
                    for j, v in vals:
                        t = di[j] + v
                        if t < best:
                            best = t
                row[i] = best
            dp[mask] = row
        return dp[full][n]

