            rem = [j for j in range(n) if not (mask >> j) & 1]
            alice = bin(mask).count('1') % 2 == 0
            if mask == 0:
                sources = [n]
            else:
                sources = [i for i in range(n) if (mask >> i) & 1]
            nxt = [(j, dp[mask | (1 << j)][j]) for j in rem]
            for i in sources:
                d = dist[i]
                if alice:
                    best = -1
                    for j, v in nxt:
                        t = d[j] + v
                        if t > best:
