class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        rows_of = defaultdict(set)
        for i, row in enumerate(grid):
            for v in row:
                rows_of[v].add(i)
        size = 1 << n
        NEG = -1
        dp = [NEG] * size
        dp[0] = 0
        for v in sorted(rows_of.keys(), reverse=True):
            new = dp[:]
            rs = rows_of[v]
            for mask in range(size):
                if dp[mask] < 0:
                    continue
                for r in rs:
                    if not (mask >> r) & 1:
                        nm = mask | (1 << r)
                        val = dp[mask] + v
                        if val > new[nm]:
                            new[nm] = val
            dp = new
        return max(dp)

