from typing import List

class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)
        FULL = (1 << 128) - 1
        M = []
        for b in range(7):
            m = 0
            for v in range(128):
                if not (v >> b) & 1:
                    m |= 1 << v
            M.append(m)

        def trans(mask, x):
            for b in range(7):
                if (x >> b) & 1:
                    mb = M[b]
                    mask = ((mask & mb) << (1 << b)) | (mask & ~mb & FULL)
            return mask

        def compute(arr):
            # res[i] = mask for choosing k from arr[0..i-1]
            res = [0] * (len(arr) + 1)
            dp = [0] * (k + 1)
            dp[0] = 1  # OR value 0 with zero elements
            for i, x in enumerate(arr):
                for j in range(min(i + 1, k), 0, -1):
                    if dp[j - 1]:
                        dp[j] |= trans(dp[j - 1], x)
                res[i + 1] = dp[k]
            return res

        pre = compute(nums)
        sufr = compute(nums[::-1])
        # suf[i] = choose k from nums[i..n-1] = sufr[n-i]
        best = 0
        cache = {}
        for i in range(k, n - k + 1):
            a = pre[i]
            b = sufr[n - i]
            if not a or not b:
                continue
            key = (a, b)
            if key in cache:
                continue
            A = [v for v in range(128) if (a >> v) & 1]
            B = [v for v in range(128) if (b >> v) & 1]
            cur = 0
            for u in A:
                for w in B:
                    t = u ^ w
                    if t > cur:
                        cur = t
            cache[key] = cur
            if cur > best:
                best = cur
        return best
