    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        mp = {'F': 0, 'W': 1, 'E': 2}
        size = 2 * n + 1
        off = n
        dp = [[0] * size for _ in range(3)]
        a0 = mp[s[0]]
        for b in range(3):
            if b == a0:
                d = 0
            elif b == (a0 + 1) % 3:
                d = 1
            else:
                d = -1
            dp[b][off + d] = 1
        for i in range(1, n):
            a = mp[s[i]]
            new = []
            for b in range(3):
                p1, p2 = [p for p in range(3) if p != b]
                o1, o2 = dp[p1], dp[p2]
                if b == a:
                    d = 0
                elif b == (a + 1) % 3:
                    d = 1
                else:
                    d = -1
                tot = [(x + y) % MOD for x, y in zip(o1, o2)]
                if d == 0:
                    nb = tot
                elif d == 1:
                    nb = [0] + tot[:-1]
                else:
                    nb = tot[1:] + [0]
                new.append(nb)
            dp = new
        ans = 0
        for b in range(3):
            ans += sum(dp[b][off + 1:])
        return ans % MOD

