    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        mp = {'F': 0, 'W': 1, 'E': 2}
        n = len(s)
        size = 2 * n + 1
        off = n

        def delta(a, b):
            if a == b:
                return 0
            if b == (a + 1) % 3:
                return 1
            return -1

        a0 = mp[s[0]]
        dp = [[0] * size for _ in range(3)]
        for b in range(3):
            dp[b][off + delta(a0, b)] = 1

        for i in range(1, n):
            a = mp[s[i]]
            new = [[0] * size for _ in range(3)]
            for b in range(3):
                d = delta(a, b)
                acc = new[b]
                for last in range(3):
                    if last == b:
                        continue
                    p = dp[last]
                    if d == 0:
                        acc = [x + y for x, y in zip(acc, p)]
                    elif d == 1:
                        acc = [acc[0]] + [x + y for x, y in zip(acc[1:], p[:-1])]
                    else:
                        acc = [x + y for x, y in zip(acc[:-1], p[1:])] + [acc[-1]]
                new[b] = [x % MOD for x in acc]
            dp = new

        total = 0
        for b in range(3):
            total += sum(dp[b][off + 1:])
        return total % MOD

