The array is small (at most 100 elements), so we can simply try every option: keep the whole array, or remove each element in turn. For each candidate array we compute the GCD and LCM of its elements and take their product. An empty array scores 0.

```python
from typing import List
from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def score(arr):
            if not arr:
                return 0
            g = 0
            l = 1
            for x in arr:
                g = gcd(g, x)
                l = l * x // gcd(l, x)
            return g * l

        best = score(nums)
        for i in range(len(nums)):
            best = max(best, score(nums[:i] + nums[i+1:]))
        return best
