    def subsequencePairCount(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        M = max(nums)
        n = len(nums)
        freq = [0] * (M + 1)
        for x in nums:
            freq[x] += 1
        cnt = [0] * (M + 1)
        for d in range(1, M + 1):
            s = 0
            for m in range(d, M + 1, d):
                s += freq[m]
            cnt[d] = s
        # mobius
        mu = [1] * (M + 1)
        is_p = [True] * (M + 1)
        for p in range(2, M + 1):
            if is_p[p]:
                for m in range(p, M + 1, p):
                    if m > p:
                        is_p[m] = False
                    mu[m] = -mu[m]
                pp = p * p
                for m in range(pp, M + 1, pp):
                    mu[m] = 0
        p2 = [1] * (2 * n + 1)
        p3 = [1] * (n + 1)
        for i in range(1, 2 * n + 1):
            p2[i] = p2[i - 1] * 2 % MOD
        for i in range(1, n + 1):
            p3[i] = p3[i - 1] * 3 % MOD

        def f(a, b):
            ca, cb = cnt[a], cnt[b]
            l = a * b // gcd(a, b)
            cl = cnt[l] if l <= M else 0
            return (p3[cl] * p2[ca + cb - 2 * cl] - p2[ca] - p2[cb] + 1) % MOD

        ans = 0
        for g in range(1, M + 1):
            if cnt[g] == 0:
                continue
            k = M // g
            tot = 0
            for i in range(1, k + 1):
                if mu[i] == 0:
                    continue
                a = g * i
                if cnt[a] == 0:
                    continue
                for j in range(1, k + 1):
                    if mu[j] == 0:
                        continue
                    b = g * j
                    if cnt[b] == 0:
                        continue
                    tot += mu[i] * mu[j] * f(a, b)
            ans = (ans + tot) % MOD
        return ans % MOD

