class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        for _ in range(t):
            z = cnt[25]
            new = [0] + cnt[:25]
            new[0] = z % MOD
            new[1] = (new[1] + z) % MOD
            cnt = new
        return sum(cnt) % MOD

