        n = len(nums)
        p = [0] * (n + 1)
        for i, x in enumerate(nums):
            p[i + 1] = p[i] + x
        best = float('inf')
        for i in range(n):
            for length in range(l, r + 1):
                j = i + length
                if j > n:
                    break
                s = p[j] - p[i]
                if 0 < s < best:
                    best = s
        return -1 if best == float('inf') else best
