from typing import List

class Solution:
    def minDifference(self, nums: List[int]) -> int:
        n = len(nums)
        base = 0
        for i in range(n - 1):
            if nums[i] != -1 and nums[i+1] != -1:
                base = max(base, abs(nums[i] - nums[i+1]))
        known = [i for i in range(n) if nums[i] != -1]
        if len(known) == n:
            return base
        if not known:
            return 0
        lo, hi = float('inf'), 0
        for i in range(n):
            if nums[i] != -1:
                if (i > 0 and nums[i-1] == -1) or (i < n-1 and nums[i+1] == -1):
                    lo = min(lo, nums[i]); hi = max(hi, nums[i])
        singles = []  # one endpoint
        pairs = []    # (a, b, count)
        if known[0] > 0:
            singles.append(nums[known[0]])
        if known[-1] < n - 1:
            singles.append(nums[known[-1]])
        for k in range(len(known) - 1):
            i, j = known[k], known[k+1]
            if j > i + 1:
                pairs.append((nums[i], nums[j], j - i - 1))

        def check(d):
            x = lo + d
            y = hi - d
            for a in singles:
                if min(abs(a - x), abs(a - y)) > d:
                    return False
            xy = abs(x - y) <= d
            for a, b, c in pairs:
                ax = abs(a - x) <= d; ay = abs(a - y) <= d
                bx = abs(b - x) <= d; by = abs(b - y) <= d
                if (ax and bx) or (ay and by):
                    continue
                if c == 1:
                    return False
                if (ax or ay) and (bx or by) and xy:
                    continue
                return False
            return True

        l, r = base, 10**9
        while l < r:
            m = (l + r) // 2
            if check(m):
                r = m
            else:
                l = m + 1
        return l
