        for a, b, _ in segs:
            if a is not None:
                neigh.append(a)
            if b is not None:
                neigh.append(b)
        lo, hi = min(neigh), max(neigh)

        def ok(d):
            x = lo + d
            y = hi - d
            for a, b, L in segs:
                if a is None or b is None:
                    v = a if a is not None else b
                    if min(abs(v - x), abs(v - y)) > d:
                        return False
