class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        full = (1 << m) - 1
        L = [1] * (1 << m)
        for mask in range(1, 1 << m):
            l = 1
            for i in range(m):
                if mask >> i & 1:
                    l = l * target[i] // gcd(l, target[i])
            L[mask] = l
        INF = float('inf')
        dp = [INF] * (1 << m)
        dp[0] = 0
        subs = list(range(1, 1 << m))
        for x in nums:
            cost = [(-x) % L[s] for s in range(1 << m)]
            new = dp[:]
            for mask in range(1 << m):
                d = dp[mask]
                if d == INF:
                    continue
                for s in subs:
                    nm = mask | s
                    if nm == mask:
                        continue
                    v = d + cost[s]
                    if v < new[nm]:
                        new[nm] = v
            dp = new
        return dp[full]

