class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        nums.sort()
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i-1] * i % MOD
        inv = [1] * (n + 1)
        inv[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            inv[i-1] = inv[i] * i % MOD
        t = k - 1
        def C(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * inv[b] % MOD * inv[a-b] % MOD
        f = [0] * n
        f[0] = 1
        for m in range(n - 1):
            f[m+1] = (2 * f[m] - C(m, t)) % MOD
        ans = 0
        for i in range(n):
            ans = (ans + nums[i] % MOD * ((f[i] + f[n-1-i]) % MOD)) % MOD
        return ans

