            segs.sort()
            n = len(segs)
            res = 0
            j = 0
            cur = 0
            for i in range(n):
                end = segs[i][0] + k - 1
                if j < i:
                    j = i
                    cur = 0
                while j < n and segs[j][1] <= end:
                    cur += (segs[j][1] - segs[j][0] + 1) * segs[j][2]
