    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        adj = [[] for _ in range(n)]
        for a, b, w in edges:
            adj[b].append((a, w))
        INF = float('inf')
        dist = [INF] * n
        dist[0] = 0
        pq = [(0, 0)]
        visited = [False] * n
        ans = 0
        cnt = 0
        while pq:
            d, u = heapq.heappop(pq)
            if visited[u]:
                continue
            visited[u] = True
            cnt += 1
            if d > ans:
                ans = d
            for v, w in adj[u]:
                if not visited[v]:
                    nd = max(d, w)
                    if nd < dist[v]:
                        dist[v] = nd
                        heapq.heappush(pq, (nd, v))
        return ans if cnt == n else -1

