class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums):
            pre[i + 1] = pre[i] + x
        NEG = float('-inf')
        prev = [0] * (n + 1)  # dp for j-1
        for j in range(1, k + 1):
            cur = [NEG] * (n + 1)
            best = NEG
            start = j * m
            for i in range(start, n + 1):
                l = i - m
                v = prev[l]
                if v != NEG:
                    c = v - pre[l]
                    if c > best:
                        best = c
                cand = best + pre[i] if best != NEG else NEG
                if cur[i - 1] > cand:
                    cand = cur[i - 1]
                cur[i] = cand
            prev = cur
        return prev[n]

