class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        T = []
        for di, dj in dirs:
            t = [[0] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if di == 1 else range(n)
            for i in rows:
                gi = grid[i]
                ti = t[i]
                ni = i + di
                inrow = 0 <= ni < n
                for j in range(m):
                    v = gi[j]
                    if v == 1:
                        continue
                    nj = j + dj
                    if inrow and 0 <= nj < m and grid[ni][nj] == 2 - v:
                        ti[j] = 1 + t[ni][nj]
                    else:
                        ti[j] = 1
            T.append(t)

        best = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue
                for d in range(4):
                    di, dj = dirs[d]
                    d2 = (d + 1) % 4
                    ei, ej = dirs[d2]
                    t2 = T[d2]
                    pi, pj, k = i, j, 0
                    while True:
                        exp = 2 if k == 0 else 2 - grid[pi][pj]
                        qi, qj = pi + ei, pj + ej
                        if 0 <= qi < n and 0 <= qj < m and grid[qi][qj] == exp:
                            cand = k + 1 + t2[qi][qj]
                        else:
                            cand = k + 1
                        if cand > best:
                            best = cand
                        ni, nj = pi + di, pj + dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == exp:
                            pi, pj = ni, nj
                            k += 1
                        else:
                            break
        return best

