class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def f(n):
            if n <= 0:
                return 0
            total = 0
            k = 1
            lo = 1
            while lo <= n:
                hi = lo * 4 - 1
                total += k * (min(hi, n) - lo + 1)
                lo *= 4
                k += 1
            return total
        ans = 0
        for l, r in queries:
            s = f(r) - f(l - 1)
            ans += (s + 1) // 2
        return ans

