                need = (X + points[i] - 1) // points[i]
                rem = need - prev
                if i == n - 1 and rem <= 0:
                    break
                moves += 1
                k = rem - 1
                if k > 0:
                    moves += 2 * k
                    prev = k
                else:
                    prev = 0
                if moves > m:
                    return False
            return moves <= m

        lo, hi = 0, min(points) * ((m + 1) // 2) + 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

