    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = ['a'] * L
        diff = [0] * (L + 1)
        s2 = list(str2)
        for i in range(n):
            if str1[i] == 'T':
                word[i:i + m] = s2
                diff[i] += 1
                diff[i + m] -= 1
        free = [False] * L
        c = 0
        for p in range(L):
            c += diff[p]
            if c == 0:
                free[p] = True
        lastFree = [-1] * L
        lf = -1
        for p in range(L):
            if free[p]:
                lf = p
            lastFree[p] = lf
        for i in range(n):
            if str1[i] == 'F':
                if ''.join(word[i:i + m]) == str2:
                    j = lastFree[i + m - 1]
                    if j < i:
                        return ""
                    word[j] = 'b'
        w = ''.join(word)
        for i in range(n):
            eq = w[i:i + m] == str2
            if eq != (str1[i] == 'T'):
                return ""
        return w

