class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1
        fact = [1] * (n + 2)
        for i in range(1, n + 2):
            fact[i] = min(fact[i-1] * i, CAP)

        def ways(o, e, nxt_odd):
            # arrangements of remaining o odds, e evens, starting with parity nxt_odd
            if o == 0 and e == 0:
                return 1
            if nxt_odd:
                if not (o == e or o == e + 1):
                    return 0
            else:
                if not (e == o or e == o + 1):
                    return 0
            return min(fact[o] * fact[e], CAP)

        used = [False] * (n + 1)
        o = (n + 1) // 2
        e = n // 2
        res = []
        prev = -1
        for pos in range(n):
            placed = False
            for x in range(1, n + 1):
                if used[x]:
                    continue
                if prev != -1 and (x % 2) == (prev % 2):
                    continue
                no, ne = o, e
                if x % 2 == 1:
                    no -= 1
                else:
                    ne -= 1
                # next parity is opposite of x
                cnt = ways(no, ne, x % 2 == 0)
                if k > cnt:
                    k -= cnt
                    continue
                used[x] = True
                res.append(x)
                prev = x
                o, e = no, ne
                placed = True
                break
            if not placed:
                return []
        return res

