class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        prev = np.zeros((n, k + 1), dtype=np.int32)
        for i in range(n - 1, -1, -1):
            cur = np.zeros((n, k + 1), dtype=np.int32)
            cur[i] = 1
            for j in range(i + 1, n):
                v = np.maximum(prev[j], cur[j - 1])
                d = abs(ord(s[i]) - ord(s[j]))
                cost = min(d, 26 - d)
                if cost <= k:
                    v[cost:] = np.maximum(v[cost:], prev[j - 1][:k + 1 - cost] + 2)
                cur[j] = v
            prev = cur
        return int(prev[n - 1][k])

