    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        a = [ord(ch) - 97 for ch in s]
        K = k + 1
        prev = np.zeros((n, K), dtype=np.int32)
        zeros = np.zeros(K, dtype=np.int32)
        for i in range(n - 1, -1, -1):
            cur = np.zeros((n, K), dtype=np.int32)
            cur[i, :] = 1
            for j in range(i + 1, n):
                d = abs(a[i] - a[j])
                cost = min(d, 26 - d)
                row = np.maximum(prev[j], cur[j - 1])
                if cost <= k:
                    if j - 1 >= i + 1:
                        inner = prev[j - 1]
                    else:
                        inner = zeros
                    cand = inner[:K - cost] + 2
                    row[cost:] = np.maximum(row[cost:], cand)
                cur[j] = row
            prev = cur
        return int(prev[n - 1][k])

