class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        ans = 0
        for i, t in enumerate(nums):
            if t == 0:
                continue
            mask = (1 << (t + 1)) - 1
            bits = 1
            found = -1
            for k, (l, r, v) in enumerate(queries):
                if l <= i <= r:
                    bits = (bits | (bits << v)) & mask
                    if (bits >> t) & 1:
                        found = k + 1
                        break
            if found == -1:
                return -1
            ans = max(ans, found)
        return ans

