import sys
def main():
    data=sys.stdin.read().split()
    n=int(data[0]); A=list(map(int,data[1:1+n])); S=data[1+n]
    mex=[[[0]*3 for _ in range(3)] for _ in range(3)]
    for a in range(3):
        for b in range(3):
            for c in range(3):
                s={a,b,c}
                m=0
                while m in s: m+=1
                mex[a][b][c]=m
    cm=[0,0,0]; cx=[0,0,0]
    for i in range(n):
        if S[i]=='X': cx[A[i]]+=1
    ans=0
    for i in range(n):
        ch=S[i]; v=A[i]
        if ch=='M': cm[v]+=1
        elif ch=='X': cx[v]-=1
        else:
            t=0
            for a in range(3):
                if cm[a]:
                    row=mex[a][v]
                    t+=cm[a]*(cx[0]*row[0]+cx[1]*row[1]+cx[2]*row[2])
