import sys
from itertools import product

def main():
    data = sys.stdin.read().split()
    M = int(data[0])
    S = data[1:4]
    best = None
    for d in "0123456789":
        lists = []
        ok = True
        for s in S:
            ts = [t for t in range(3 * M) if s[t % M] == d][:3]
            if not ts:
                ok = False
                break
            lists.append(ts)
        if not ok:
            continue
        for a, b, c in product(*lists):
            if a != b and b != c and a != c:
                v = max(a, b, c)
                if best is None or v < best:
                    best = v
    print(best if best is not None else -1)

main()

import sys

def main():
    lines = [l.strip() for l in sys.stdin.read().split('\n') if l.strip()]
    pieces = []
    for i in range(3):
        cells = []
        for r in range(4):
            for c in range(4):
                if lines[i*4+r][c] == '#':
                    cells.append((r, c))
        pieces.append(cells)
    total = sum(len(p) for p in pieces)
    if total != 16:
        print("No")
        return
    def norm(cells):
        mr = min(r for r, c in cells)
        mc = min(c for r, c in cells)
        return [(r-mr, c-mc) for r, c in cells]
    placements = []
    for p in pieces:
        masks = set()
        cur = norm(p)
        for _ in range(4):
            h = max(r for r, c in cur)
            w = max(c for r, c in cur)
            for dr in range(4 - h):
                for dc in range(4 - w):
                    m = 0
                    for r, c in cur:
                        m |= 1 << ((r+dr)*4 + (c+dc))
                    masks.add(m)
            cur = norm([(c, -r) for r, c in cur])
        placements.append(masks)
    full = (1 << 16) - 1
    s3 = placements[2]
    for a in placements[0]:
        for b in placements[1]:
            if a & b:
                continue
            if (full ^ (a | b)) in s3:
                print("Yes")
                return
    print("No")

