import sys
def lcp(a, b):
    n = min(len(a), len(b))
    i = 0
    B = 64
    while i + B <= n and a[i:i+B] == b[i:i+B]:
        i += B
    while i < n and a[i] == b[i]:
        i += 1
    return i

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); t = data[1]
    lt = len(t)
    res = []
    for k in range(n):
        s = data[2+k]
        ls = len(s)
        ok = False
        if ls == lt:
            if s == t:
                ok = True
            else:
                i = lcp(s, t)
                ok = s[i+1:] == t[i+1:]
        elif ls == lt + 1 or ls + 1 == lt:
            if ls > lt:
                a, b = s, t
            else:
                a, b = t, s
            i = lcp(a, b)
            ok = a[i+1:] == b[i:]
        if ok:
            res.append(k+1)
    out = [str(len(res)), " ".join(map(str, res))]
    sys.stdout.write("\n".join(out) + "\n")

main()

