def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); T = data[1].decode()
    m = len(T)
    A = []
    cntB = [0]*(m+2)
    for idx in range(n):
        s = data[2+idx].decode()
        k = 0
        if m > 0:
            for c in s:
                if c == T[k]:
                    k += 1
                    if k == m:
                        break
        A.append(k)
        k = 0
        p = m - 1
        for c in reversed(s):
            if c == T[p]:
                p -= 1
                k += 1
                if p < 0:
                    break
        cntB[k] += 1
    for k in range(m-1, -1, -1):
        cntB[k] += cntB[k+1]
    ans = 0
    for a in A:
        need = m - a
        if need < 0: need = 0
        ans += cntB[need]
    print(ans)
