import sys
from itertools import permutations

def main():
    d = sys.stdin.read().split()
    n = int(d[0]); R = d[1]; C = d[2]
    L = "ABC"
    rows = [[] for _ in range(3)]
    for p in permutations(range(n), 3):
        first = min(p)
        letter = p.index(first)
        rows[letter].append(p)
    mask = [0]*n
    grid = [['.']*n for _ in range(n)]
    sys.setrecursionlimit(10000)

    def rec(i):
        if i == n:
            return all(m == 7 for m in mask)
        rem = n - i
        for j in range(n):
            if 3 - bin(mask[j]).count('1') > rem:
                return False
        for p in rows[L.index(R[i])]:
            ok = True
            for k in range(3):
                j = p[k]
                if mask[j] >> k & 1:
                    ok = False; break
                if mask[j] == 0 and C[j] != L[k]:
                    ok = False; break
            if not ok:
                continue
            for k in range(3):
                mask[p[k]] |= 1 << k
                grid[i][p[k]] = L[k]
            if rec(i+1):
                return True
            for k in range(3):
                mask[p[k]] ^= 1 << k
                grid[i][p[k]] = '.'
        return False

    if rec(0):
        print("Yes")
        print("\n".join("".join(r) for r in grid))
    else:
        print("No")

main()

