def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    s = list(data[2])
    t = data[3]

    def ok(i):
        # Window [i, i+m) can be undone: every char is '#' or matches T,
        # and at least one char is not '#'.
        has = False
        for j in range(m):
            c = s[i + j]
            if c == '#':
                continue
            if c != t[j]:
                return False
            has = True
        return has

