    for i in range(n - m + 1):
        if ok(i):
            q.append(i)

    while q:
        i = q.popleft()
        if not ok(i):
            continue
        for j in range(m):
            s[i + j] = '#'
        for k in range(max(0, i - m + 1), min(n - m, i + m - 1) + 1):
            if ok(k):
                q.append(k)

