from itertools import permutations

def main():
    data = sys.stdin.read().split()
    idx = 0
    H = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1
    A = []
    for i in range(H):
        A.append([int(x) for x in data[idx:idx+W]]); idx += W
    B = []
    for i in range(H):
        B.append([int(x) for x in data[idx:idx+W]]); idx += W

    def inv(p):
        c = 0
        n = len(p)
        for i in range(n):
            for j in range(i+1, n):
                if p[i] > p[j]:
                    c += 1
        return c

    rps = [(p, inv(p)) for p in permutations(range(H))]
    cps = [(q, inv(q)) for q in permutations(range(W))]
    best = -1
    for p, ip in rps:
        rows = [A[p[i]] for i in range(H)]
        for q, iq in cps:
            cost = ip + iq
            if best != -1 and cost >= best:
                continue
            ok = True
            for i in range(H):
                r = rows[i]
                b = B[i]
                for j in range(W):
                    if r[q[j]] != b[j]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                best = cost
    print(best)

main()

