import sys
def main():
    data=sys.stdin.buffer.read().split()
    n=int(data[0]); a=list(map(int,data[1:1+n]))
    M=max(a)+1
    if M<2: M=2
    spf=list(range(M))
    i=2
    while i*i<M:
        if spf[i]==i:
            for j in range(i*i,M,i):
                if spf[j]==j: spf[j]=i
        i+=1
    z=0
    cnt={}
    cache={}
    for x in a:
        if x==0:
            z+=1; continue
        if x in cache:
            s=cache[x]
        else:
            y=x; s=1
            while y>1:
                p=spf[y]; c=0
                while y%p==0:
                    y//=p; c^=1
                if c: s*=p
            cache[x]=s
        cnt[s]=cnt.get(s,0)+1
    ans=z*(n-z)+z*(z-1)//2
    for c in cnt.values():
        ans+=c*(c-1)//2
    print(ans)
