import numpy as np

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    A = [int(data[1+2*i]) for i in range(n)]
    B = [int(data[2+2*i]) for i in range(n)]
    pairs = []
    for i in range(n):
        for j in range(i+1, n):
            if A[i] == A[j] or B[i] == B[j]:
                pairs.append((1 << i) | (1 << j))
    size = 1 << n
    masks = np.arange(size, dtype=np.int64)
    pc = np.zeros(size, dtype=np.int64)
    for b in range(n):
        pc += (masks >> b) & 1
    win = np.zeros(size, dtype=bool)
    layers = [masks[pc == k] for k in range(n + 1)]
    for k in range(2, n + 1):
        if (n - k) % 2 != 0:
            continue
        L = layers[k]
        if len(L) == 0:
            continue
        for p in pairs:
            sel = L[(L & p) == p]
            if len(sel) == 0:
                continue
            win[sel] = win[sel] | ~win[sel ^ p]
    print("Takahashi" if win[size - 1] else "Aoki")

main()

