def main():
    data=sys.stdin.buffer.read().split()
    H=int(data[0]); W=int(data[1]); Y=int(data[2])
    W2=W+2
    N=(H+2)*W2
    A=[0]*N
    vis=bytearray([1])*N
    idx=3
    maxA=0
    for i in range(H):
        base=(i+1)*W2+1
        row=list(map(int,data[idx:idx+W])); idx+=W
        A[base:base+W]=row
        vis[base:base+W]=bytes(W)
        m=max(row)
        if m>maxA: maxA=m
    buckets=[[] for _ in range(maxA+2)]
    # seed boundary cells
    for i in range(H):
        for j in range(W):
            if i==0 or i==H-1 or j==0 or j==W-1:
                c=(i+1)*W2+j+1
                if not vis[c]:
                    vis[c]=1
                    buckets[A[c]].append(c)
    cnt=[0]*(maxA+2)
    for L in range(1,maxA+1):
        b=buckets[L]
        if not b: continue
        i=0
        app=b.append
        while i<len(b):
            c=b[i]; i+=1
            nb=c-1
            if not vis[nb]:
                vis[nb]=1; k=A[nb]
                if k<=L: app(nb)
                else: buckets[k].append(nb)
            nb=c+1
            if not vis[nb]:
                vis[nb]=1; k=A[nb]
                if k<=L: app(nb)
                else: buckets[k].append(nb)
            nb=c-W2
            if not vis[nb]:
                vis[nb]=1; k=A[nb]
                if k<=L: app(nb)
                else: buckets[k].append(nb)
            nb=c+W2
