import sys
def main():
    data = sys.stdin.buffer.read().split()
    H = int(data[0]); W = int(data[1]); Y = int(data[2])
    W2 = W + 2
    N = (H + 2) * W2
    A = [0] * N
    vis = bytearray(b'\x01') * N
    idx = 3
    maxA = 0
    for i in range(H):
        base = (i + 1) * W2 + 1
        row = data[idx:idx + W]
        idx += W
        vals = list(map(int, row))
        A[base:base + W] = vals
        vis[base:base + W] = bytes(W)
        m = max(vals)
        if m > maxA:
            maxA = m
    buckets = [[] for _ in range(maxA + 2)]
    # border cells
    border = set()
    for j in range(W):
        border.add(1 * W2 + 1 + j)
        border.add(H * W2 + 1 + j)
    for i in range(H):
        border.add((i + 1) * W2 + 1)
        border.add((i + 1) * W2 + W)
    for c in border:
        vis[c] = 1
        buckets[A[c]].append(c)
    cnt = [0] * (maxA + 2)
    for L in range(1, maxA + 1):
        b = buckets[L]
        if not b:
            continue
        k = 0
        app = b.append
        while b:
            c = b.pop()
            k += 1
            nb = c - 1
            if not vis[nb]:
                vis[nb] = 1
                a = A[nb]
                if a <= L: app(nb)
                else: buckets[a].append(nb)
            nb = c + 1
            if not vis[nb]:
                vis[nb] = 1
                a = A[nb]
                if a <= L: app(nb)
                else: buckets[a].append(nb)
            nb = c - W2
            if not vis[nb]:
                vis[nb] = 1
                a = A[nb]
                if a <= L: app(nb)
                else: buckets[a].append(nb)
            nb = c + W2
            if not vis[nb]:
                vis[nb] = 1
                a = A[nb]
                if a <= L: app(nb)
                else: buckets[a].append(nb)
        cnt[L] = k
    total = H * W
    out = []
    s = 0
    for i in range(1, Y + 1):
        if i <= maxA:
            s += cnt[i]
        out.append(total - s)
    sys.stdout.write("\n".join(map(str, out)) + "\n")
main()

import sys
from functools import lru_cache
sys.setrecursionlimit(10000)

def main():
    N = int(input())
    divs = []
    i = 1
    while i * i <= N:
        if N % i == 0:
            divs.append(i)
            if i != N // i:
                divs.append(N // i)
        i += 1
    divs.sort()
    good = [d for d in divs if d >= 2 and '0' not in str(d)]

    @lru_cache(maxsize=None)
    def f(n):
        s = str(n)
        if '0' not in s and s == s[::-1]:
            return s
        for x in good:
            if x * x > n:
                break
            if n % x:
                continue
            r = int(str(x)[::-1])
            m = n // x
            if m % r:
                continue
            inner = f(m // r)
            if inner is not None:
                return str(x) + "*" + inner + "*" + str(r)
        return None

    res = f(N)
    print(res if res is not None else -1)

main()

