import sys, bisect
def main():
    d=sys.stdin.buffer.read().split()
    n=int(d[0]); m=int(d[1])
    a=sorted(map(int,d[2:2+n]))
    if sum(a)<=m:
        print("infinite"); return
    pre=[0]*(n+1)
    for i in range(n):
        pre[i+1]=pre[i]+a[i]
    lo,hi=0,a[-1]
    while hi-lo>1:
        mid=(lo+hi)//2
        k=bisect.bisect_left(a,mid)
        if pre[k]+mid*(n-k)<=m:
            lo=mid
        else:
            hi=mid
    print(lo)
