import sys
def main():
    data=sys.stdin.buffer.read().split()
    H=int(data[0]); W=int(data[1]); Q=int(data[2])
    W2=W+2; H2=H+2
    Lp=[0]*(H*W2); Rp=[0]*(H*W2)
    for r in range(H):
        b=r*W2
        for c in range(W2):
            Lp[b+c]=b+c; Rp[b+c]=b+c
    Up=[0]*(W*H2); Dp=[0]*(W*H2)
    for c in range(W):
        b=c*H2
        for r in range(H2):
            Up[b+r]=b+r; Dp[b+r]=b+r
    alive=bytearray([1])*(H*W)
    cnt=H*W
    def find(p,x):
        root=x
        while p[root]!=root:
            root=p[root]
        while p[x]!=root:
            nx=p[x]; p[x]=root; x=nx
        return root
    def destroy(r,c):
        # r 0-based, c 0-based
        alive[r*W+c]=0
        i=r*W2+c+1
        Lp[i]=i-1; Rp[i]=i+1
        j=c*H2+r+1
        Up[j]=j-1; Dp[j]=j+1
    idx=3
    for _ in range(Q):
        r=int(data[idx])-1; c=int(data[idx+1])-1; idx+=2
        if alive[r*W+c]:
            destroy(r,c); cnt-=1
            continue
        targets=[]
        b=c*H2
        u=find(Up,b+r)-b  # position r+1 coords; r (0-based) => index r means row r-1 in 1-based... 
        # index b+r corresponds to 1-based row r, i.e., 0-based r-1 (upper neighbor)
        if u>=1: targets.append((u-1,c))
        d=find(Dp,b+r+2)-b
        if d<=H: targets.append((d-1,c))
        b=r*W2
        l=find(Lp,b+c)-b
        if l>=1: targets.append((r,l-1))
        rr=find(Rp,b+c+2)-b
        if rr<=W: targets.append((r,rr-1))
        for (a,e) in targets:
            if alive[a*W+e]:
                destroy(a,e); cnt-=1
    print(cnt)
