            b %= m
        y_max = a * n + b
        if y_max < m:
            break
        n, b = divmod(y_max, m)
        m, a = a, m
    return ans

def cmp(p, q):
    a1, b1, c1 = p
    a2, b2, c2 = q
    l = a1 * b2; r = a2 * b1
    if l != r:
        return -1 if l < r else 1
    l = c1 * b2; r = c2 * b1
    if l != r:
        return -1 if l < r else 1
    return 0

def inter(l1, l2):
    a1, b1, c1 = l1
    a2, b2, c2 = l2
    return (c2 * b1 - c1 * b2, a2 * b1 - a1 * b2)

def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    T = int(data[pos]); pos += 1
    out = []
    key = cmp_to_key(cmp)
    for _ in range(T):
        n = int(data[pos]); pos += 1
        lines = []
        X = None
        for i in range(n):
            a = int(data[pos]); b = int(data[pos+1]); c = int(data[pos+2]) - 1
            pos += 3
            lines.append((a, b, c))
            v = (c - b) // a if c - b >= 0 else -1
            if X is None or v < X:
                X = v
