            continue
        lines.sort(key=key)
        uniq = []
        for ln in lines:
            if uniq and uniq[-1][0] * ln[1] == ln[0] * uniq[-1][1]:
                continue
            uniq.append(ln)
        st = []
        for ln in uniq:
            while len(st) >= 2:
                n13, d13 = inter(st[-2], ln)
                n12, d12 = inter(st[-2], st[-1])
                if n13 * d12 <= n12 * d13:
                    st.pop()
                else:
                    break
            st.append(ln)
