            if index[v] == -1:
                dfs(v)
                if low[v] < low[u]: low[u] = low[v]
            elif onst[v]:
                if index[v] < low[u]: low[u] = index[v]
        if low[u] == index[u]:
            c = ncomp[0]; ncomp[0] += 1
            while True:
                w = st.pop(); onst[w] = False; comp[w] = c
                if w == u: break
