def main():
    A,B,M=map(int,sys.stdin.read().split())
    N=A*B-1
    # hook formula for lambda = (A^{B-1}, A-1)
    rows=[A]*(B-1)+[A-1]
    cols=[0]*A
    for r in rows:
        for j in range(r):
            cols[j]+=1
    num=1
    for i in range(1,N+1):
        num=num*i%M
    den=1
    for i in range(B):
        for j in range(rows[i]):
            h=(rows[i]-j-1)+(cols[j]-i-1)+1
            den=den*h%M
    f=num*pow(den,M-2,M)%M
    # linear extensions DP
    cur={tuple([0]*A):1}
    for step in range(N):
        nxt={}
        for st,v in cur.items():
            l=list(st)
            for j in range(A-1):
                hj=l[j]
                if hj<B and (j==0 or l[j-1]>hj):
                    l[j]=hj+1
                    t=tuple(l)
                    nxt[t]=(nxt.get(t,0)+v)%M
                    l[j]=hj
            hA=l[A-1]
            if hA<B-1 and l[A-2]>=hA+2:
                l[A-1]=hA+1
                t=tuple(l)
                nxt[t]=(nxt.get(t,0)+v)%M
                l[A-1]=hA
        cur=nxt
    L=0
    for v in cur.values():
        L=(L+v)%M
    print(f*L%M)
