import sys
from math import factorial

def main():
    A, B, M = map(int, sys.stdin.read().split())
    # f^lambda, lambda = (A^(B-1), A-1)
    lam = [A] * (B - 1) + [A - 1]
    n = A * B - 1
    # conjugate
    conj = [sum(1 for r in lam if r > j) for j in range(A)]
    hp = 1
    for i in range(B):
        for j in range(lam[i]):
            hp *= (lam[i] - j - 1) + (conj[j] - i - 1) + 1
    f = (factorial(n) // hp) % M

    # DP over ideals of poset P
    caps = [A - 1] + [A] * (B - 1)
    cur = {tuple([0] * B): 1}
    for step in range(n):
        nxt = {}
        get = nxt.get
        for t, c in cur.items():
            for i in range(B):
                r = t[i]
                j = r + 1
                if j > caps[i]:
                    continue
                if i > 0:
                    if not (t[i - 1] >= j or (i == 1 and j == A)):
                        continue
                nt = t[:i] + (j,) + t[i + 1:]
                nxt[nt] = (get(nt, 0) + c) % M
        cur = nxt
    e = sum(cur.values()) % M
    print(f * e % M)

main()

