def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    out = []
    idx = 1
    for _ in range(t):
        K = int(data[idx]); sx = int(data[idx+1]); sy = int(data[idx+2])
        tx = int(data[idx+3]); ty = int(data[idx+4])
        idx += 5

        def tile(X, Y):
            i = X // K; j = Y // K
            if (i + j) % 2 == 0:
                k = Y - j * K
                if k == 0:
                    ent = [(2*i+1, 2*j, 0)]
                elif k == K - 1:
                    ent = [(2*i+1, 2*j+2, 0)]
                else:
                    ent = [(2*i, 2*j+1, 1), (2*i+2, 2*j+1, 1),
                           (2*i+1, 2*j, k), (2*i+1, 2*j+2, K-1-k)]
            else:
                k = X - i * K
                if k == 0:
                    ent = [(2*i, 2*j+1, 0)]
                elif k == K - 1:
                    ent = [(2*i+2, 2*j+1, 0)]
                else:
                    ent = [(2*i+1, 2*j, 1), (2*i+1, 2*j+2, 1),
                           (2*i, 2*j+1, k), (2*i+2, 2*j+1, K-1-k)]
            return i, j, k, ent

        si, sj, sk, se = tile(sx, sy)
        ti, tj, tk, te = tile(tx, ty)
        best = None
        if si == ti and sj == tj:
            best = abs(sk - tk)

        if K >= 3:
            for (x1, y1, c1) in se:
                for (x2, y2, c2) in te:
                    d = max(abs(x1 - x2), abs(y1 - y2)) + c1 + c2
                    if best is None or d < best:
                        best = d
        else:
            for (x1, y1, c1) in se:
                u0 = (x1 + y1 - 1) // 2; w0 = (x1 - y1 - 1) // 2
                for (x2, y2, c2) in te:
                    u1 = (x2 + y2 - 1) // 2; w1 = (x2 - y2 - 1) // 2
                    Du = u1 - u0; Dw = w1 - w0
                    a0, b0, a1, b1 = u0, w0, u1, w1
                    if Du >= 0 and Dw >= 0:
                        a = 1; b = 0
                    elif Du >= 0 and Dw < 0:
                        a = 0; b = 0
                        b0 = -w0; b1 = -w1
                    elif Du < 0 and Dw < 0:
                        a = 0; b = 1
                        a0 = -u0; a1 = -u1; b0 = -w0; b1 = -w1
                    else:
                        a = 1; b = 1
                        a0 = -u0; a1 = -u1
                    dU = a1 - a0; dW = b1 - b0
                    nO = (a1 - a + 1) // 2 - (a0 - a + 1) // 2
                    e = (b0 - b) % 2
                    s2 = (dW + 1 - e) // 2
                    if s2 < 0:
                        s2 = 0
                    s = min(nO, s2)
                    if s < 0:
                        s = 0
                    d = dU + dW - s + c1 + c2
                    if best is None or d < best:
                        best = d
        out.append(str(best))
