import sys, math

def main():
    N = int(sys.stdin.readline())
    M = math.isqrt(N)
    if M < 2:
        print(0)
        return
    sieve = bytearray([1]) * (M + 1)
    sieve[0] = 0
    sieve[1] = 0
    for i in range(2, math.isqrt(M) + 1):
        if sieve[i]:
            sieve[i*i::i] = bytearray(len(range(i*i, M+1, i)))
    primes = [i for i in range(M + 1) if sieve[i]]
    ans = 0
    # case p^8
    for p in primes:
        if p ** 8 <= N:
            ans += 1
        else:
            break
    # case p^2 q^2
    j = len(primes) - 1
    for i, p in enumerate(primes):
        if p * p >= M:
            break
        lim = M // p
        while j >= 0 and primes[j] > lim:
            j -= 1
        if j > i:
            ans += j - i
        else:
            break
    print(ans)

