from bisect import bisect_left, bisect_right

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1]); sx = int(data[2]); sy = int(data[3])
    col = {}
    row = {}
    idx = 4
    for i in range(n):
        x = int(data[idx]); y = int(data[idx+1]); idx += 2
        if x in col:
            col[x].append(y)
        else:
            col[x] = [y]
        if y in row:
            row[y].append(x)
        else:
            row[y] = [x]
    for v in col.values():
        v.sort()
    for v in row.values():
        v.sort()
    removed = set()
    cnt = 0
    x, y = sx, sy
    for i in range(m):
        d = data[idx]; c = int(data[idx+1]); idx += 2
        if d == b'U' or d == b'D':
            ny = y + c if d == b'U' else y - c
            lst = col.get(x)
            if lst:
                lo = min(y, ny); hi = max(y, ny)
                l = bisect_left(lst, lo); r = bisect_right(lst, hi)
                if l < r:
                    for yy in lst[l:r]:
                        key = (x, yy)
                        if key not in removed:
                            removed.add(key)
                            cnt += 1
                    del lst[l:r]
            y = ny
        else:
            nx = x + c if d == b'R' else x - c
            lst = row.get(y)
            if lst:
                lo = min(x, nx); hi = max(x, nx)
                l = bisect_left(lst, lo); r = bisect_right(lst, hi)
                if l < r:
                    for xx in lst[l:r]:
                        key = (xx, y)
                        if key not in removed:
                            removed.add(key)
                            cnt += 1
                    del lst[l:r]
            x = nx
    print(x, y, cnt)

