import sys
def main():
    data=sys.stdin.buffer.read().split()
    N=int(data[0]); M=int(data[1]); A=int(data[2]); B=int(data[3])
    segs=[]
    for i in range(M):
        segs.append((int(data[4+2*i]),int(data[5+2*i])))
    if A==B:
        if (N-1)%A!=0:
            print("No"); return
        for L,R in segs:
            x=L+((1-L)%A)
            if x<=R:
                print("No"); return
        print("Yes"); return
    full=(1<<B)-1
    sel=((1<<(B-A+1))-1)<<(A-1)
    mask=1
    cur=1
    def good(mask,length):
        s=0
        while s<length and mask!=full:
            if mask & sel:
                mask=((mask<<1)|1)&full
            else:
                mask=(mask<<1)&full
                if mask==0:
                    return 0
            s+=1
        return mask
    for L,R in segs:
        # good from cur+1 to L-1
        length=L-1-cur
        if length>0:
