            for w in adj1[v]:
                if nd<d1[w]:
                    d1[w]=nd; heapq.heappush(pq,(nd,w,1))
            nd=d+X
            if nd<d0[v]:
                d0[v]=nd; heapq.heappush(pq,(nd,v,0))
    print(min(d0[n],d1[n]))
