def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    T = int(data[pos]); pos += 1
    out = []
    for _ in range(T):
        n = int(data[pos]); k = int(data[pos+1]); pos += 2
        vals = []
        ms = []
        cols = []
        for i in range(n):
            x = int(data[pos]); y = int(data[pos+1]); z = int(data[pos+2]); pos += 3
            v = (x, y, z)
            vals.append(v)
            if x >= y and x >= z:
                ms.append(x); cols.append(0)
            elif y >= z:
                ms.append(y); cols.append(1)
            else:
                ms.append(z); cols.append(2)
        order = sorted(range(n), key=lambda i: -ms[i])
        G = order[:2 * k]
        O = order[2 * k:]
        total = 0
        par = [0, 0, 0]
        for i in G:
            total += ms[i]
            par[cols[i]] ^= 1
        odd = [c for c in range(3) if par[c]]
        if not odd:
            out.append(total)
            continue
        a, b = odd
        c = 3 - a - b
        # removal candidates per color
        rem = [[] for _ in range(3)]
        Gc = [[] for _ in range(3)]
        for i in G:
            Gc[cols[i]].append(i)
        for col in range(3):
            rem[col] = heapq.nsmallest(3, Gc[col], key=lambda i: ms[i])
        add = [heapq.nlargest(3, O, key=lambda i, q=q: vals[i][q]) for q in range(3)]
        rec = {}
        for p in range(3):
            for q in range(3):
                if p != q:
                    rec[(p, q)] = heapq.nsmallest(3, Gc[p], key=lambda i, q=q: ms[i] - vals[i][q])

        def moves(p, q):
            res = []
            for (pp, qq) in ((p, q), (q, p)):
                for i in rec[(pp, qq)]:
                    res.append((ms[i] - vals[i][qq], (i,)))
                for r in rem[pp]:
                    for ad in add[qq]:
                        res.append((ms[r] - vals[ad][qq], (r, ad)))
            return res

        INF = float('inf')
        best = INF
        for l, _s in moves(a, b):
            if l < best:
                best = l
        A = moves(a, c)
        B = moves(b, c)
        for la, sa in A:
            if la >= best:
                continue
            for lb, sb in B:
                if la + lb < best:
                    ok = True
                    for x in sa:
                        if x in sb:
                            ok = False
                            break
                    if ok:
                        best = la + lb
        out.append(total - best)
    sys.stdout.write("\n".join(map(str, out)) + "\n")

