import sys, heapq

def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    T = int(data[pos]); pos += 1
    out = []
    INF = float('inf')
    for _ in range(T):
        n = int(data[pos]); k = int(data[pos+1]); pos += 2
        vals = []
        for i in range(n):
            vals.append((int(data[pos]), int(data[pos+1]), int(data[pos+2])))
            pos += 3
        ms = [max(v) for v in vals]
        cols = []
        for v in vals:
            mm = max(v)
            cols.append(0 if v[0] == mm else (1 if v[1] == mm else 2))
        order = sorted(range(n), key=lambda i: -ms[i])
        sel = order[:2*k]
        uns = order[2*k:]
        S = 0
        s = 0
        for i in sel:
            S += ms[i]
            s ^= (1 << cols[i])
        if s == 0:
            out.append(S)
            continue
        selby = [[], [], []]
        for i in sel:
            selby[cols[i]].append(i)
        remove = [heapq.nsmallest(3, ((ms[i], i) for i in selby[a])) for a in range(3)]
        add = [heapq.nlargest(3, ((vals[j][b], j) for j in uns)) for b in range(3)]
        rec = [[None]*3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    rec[a][b] = heapq.nsmallest(3, ((ms[i] - vals[i][b], i) for i in selby[a]))
        moves = {}
        for d in (3, 5, 6):
            lst = []
            for a in range(3):
                for b in range(3):
                    if a == b or ((1 << a) | (1 << b)) != d:
                        continue
                    for (mi, i) in remove[a]:
                        for (vj, j) in add[b]:
                            lst.append((mi - vj, (i, j)))
                    for (l, i) in rec[a][b]:
                        lst.append((l, (i,)))
            moves[d] = lst
        best = INF
        for (l, _) in moves[s]:
            if l < best:
                best = l
        others = [d for d in (3, 5, 6) if d != s]
        L1 = moves[others[0]]
        L2 = moves[others[1]]
        for (l1, c1) in L1:
            if l1 >= best:
                continue
            for (l2, c2) in L2:
                if l1 + l2 >= best:
                    continue
                ok = True
                for x in c1:
                    if x in c2:
                        ok = False
                        break
                if ok:
                    best = l1 + l2
        out.append(S - best)
    sys.stdout.write("\n".join(map(str, out)) + "\n")

