    primes=[2,3,5,7,11,13]
    P=6; S=1<<P; D=S+1
    v=[[0]*P for _ in range(M+1)]
    for x in range(1,M+1):
        for i,p in enumerate(primes):
            y=x;c=0
            while y%p==0: y//=p;c+=1
            v[x][i]=c
    # w[T] = sum_x prod_{p in T} v_p(x)
    w=[0]*S
    for T in range(S):
        tot=0
        for x in range(1,M+1):
            pr=1
            for i in range(P):
                if T>>i&1:
                    pr*=v[x][i]
                    if pr==0: break
            tot+=pr
        w[T]=tot%MOD
    B=[[0]*D for _ in range(D)]
    full=S-1
    for s in range(S):
        comp=full^s
        T=comp
        while True:
            B[s][s|T]=(B[s][s|T]+w[T])%MOD
            if T==0: break
            T=(T-1)&comp
        B[s][S]=sum(B[s][:S])%MOD
    B[S][S]=1
    def mul(X,Y):
        R=[]
        for i in range(D):
            Xi=X[i]
            row=[0]*D
            for k in range(D):
                a=Xi[k]
                if a:
                    Yk=Y[k]
                    for j in range(k,D):
                        b=Yk[j]
                        if b:
                            row[j]+=a*b
            R.append([t%MOD for t in row])
        return R
    # vector-matrix power: compute e0 * B^(N+1)
    e=N+1
    vec=[0]*D; vec[0]=1
    def vmul(vv,Y):
        row=[0]*D
        for k in range(D):
            a=vv[k]
            if a:
                Yk=Y[k]
                for j in range(k,D):
                    if Yk[j]: row[j]+=a*Yk[j]
        return [t%MOD for t in row]
    while e:
        if e&1: vec=vmul(vec,B)
        e>>=1
        if e: B=mul(B,B)
    print(vec[S]%MOD)
