import sys
def floor_sum(n, m, a, b):
    ans = 0
    while True:
        if a >= m:
            ans += (n - 1) * n // 2 * (a // m)
            a %= m
        if b >= m:
            ans += n * (b // m)
            b %= m
        y_max = a * n + b
        if y_max < m:
            break
        n, b = divmod(y_max, m)
        m, a = a, m
    return ans

def main():
    d = sys.stdin.read().split()
    N, M, C, K = int(d[0]), int(d[1]), int(d[2]), int(d[3])
    A = sorted(set(int(x) for x in d[4:4+N]))
    n = len(A)
    base = floor_sum(K, M, C, 0)
    cache = {}
    def f(t):
        if t <= 0:
            return 0
        if t >= M:
            return K
        if t in cache:
            return cache[t]
        v = floor_sum(K, M, C, M - t) - base
        cache[t] = v
        return v
    total = C * (K * (K - 1) // 2) - M * base
    # x < M - a_n
    total += A[0] * f(M - A[-1])
    for j in range(n):
        L = M - A[j]
        R = M if j == 0 else M - A[j - 1]
        if L < R:
            c = f(R) - f(L)
            if c:
                total += (A[j] - M) * c
    print(total)

