import numpy as np

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    A = list(map(int, data[1:1+n]))
    MOD = 998244353
    M = max(A)
    # phi sieve
    phi = list(range(M+1))
    for i in range(2, M+1):
        if phi[i] == i:
            for j in range(i, M+1, i):
                phi[j] -= phi[j] // i
    present = [False]*(M+1)
    for a in A:
        present[a] = True
    divs = [None]*(M+1)
    for v in range(1, M+1):
        if present[v]:
            divs[v] = []
    for d in range(1, M+1):
        for j in range(d, M+1, d):
            if present[j]:
                divs[j].append(d)
    dv_np = {}
    ph_np = {}
    phi_arr = np.array(phi, dtype=np.int64)
    for v in range(1, M+1):
        if present[v]:
            arr = np.array(divs[v], dtype=np.int64)
            dv_np[v] = arr
            ph_np[v] = phi_arr[arr]
    S = np.zeros(M+1, dtype=np.int64)
    ans = 0
    p = 1
    out = []
    for a in A:
        dv = dv_np[a]
        t = S[dv]
        c = int(t @ ph_np[a]) % MOD
        ans = (2*ans + c) % MOD
        out.append(ans)
        t += p
        t %= MOD
        S[dv] = t
        p = p*2 % MOD
    sys.stdout.write("\n".join(map(str, out)) + "\n")

main()

