    # d[L][j]
    d=[[0]*(k1+1) for _ in range(D+1)]
    d[0][0]=1
    for L in range(1,D+1):
        prev=d[L-1]; cur=d[L]
        for j in range(0,k1+1):
            v=prev[j]*j
            if j>=1:
                v+=prev[j-1]*(k1-(j-1))
            cur[j]=v%MOD
    S=[d[L][k1] for L in range(D+1)]
    C=[0]*(D+1)
    for t in range(1,D+1):
        if k1>=1:
            C[t]=d[t-1][k1-1]%MOD
    pw=[1]*(D+1)
    for i in range(1,D+1):
        pw[i]=pw[i-1]*(K-2)%MOD
    T=[0]*(D+1)
    for L in range(D+1):
        s=0
        for t in range(1,L+1):
            if C[t]:
                s+=C[t]*pw[L-t]
        T[L]=(S[L]-s)%MOD
    def mul(a,b):
        r=[0]*(D+1)
        for i,ai in enumerate(a):
            if ai==0: continue
            lim=D-i
            for j in range(lim+1):
                bj=b[j]
                if bj:
                    r[i+j]+=ai*bj
        return [x%MOD for x in r]
    def pw_poly(p,e):
        res=[0]*(D+1); res[0]=1
        base=p[:]
        while e:
            if e&1: res=mul(res,base)
            e>>=1
            if e: base=mul(base,base)
        return res
