    for i in range(M-1):
        if X[i+1]==X[i]: a+=1
        else: b+=1
    res=S[:]
    if a: res=mul(res,pw_poly(S,a))
    if b: res=mul(res,pw_poly(T,b))
    print(res[D]%MOD)
