    # binomials
    C=[[0]*(r+1) for _ in range(r+1)]
    for a in range(r+1):
        C[a][0]=1
        for b in range(1,a+1):
            C[a][b]=(C[a-1][b-1]+C[a-1][b])%MOD
    S=[0]*(D+1)
    for j in range(r+1):
        base=r-j
        coef=C[r][j]*(1 if j%2==0 else MOD-1)%MOD
        p=1
        for L in range(D+1):
            S[L]=(S[L]+coef*p)%MOD
            p=p*base%MOD
    c=0
    for i in range(M-1):
        if X[i+1]!=X[i]:
            c+=1
    Q=[0]*(D+1)
    p=1
    for L in range(2,D+1):
        Q[L]=p
        p=p*(K-2)%MOD
    def mul(a,b):
        res=[0]*(D+1)
        for i,ai in enumerate(a):
            if ai==0: continue
            lim=D-i
            for j in range(lim+1):
                bj=b[j]
                if bj:
                    res[i+j]+=ai*bj
        return [v%MOD for v in res]
    def pw(a,e):
        res=[0]*(D+1); res[0]=1
        while e:
            if e&1: res=mul(res,a)
            e>>=1
            if e: a=mul(a,a)
        return res
