            dx=dist[x]+1
            for y in adj[x]:
                if dist[y]<0:
                    if banned is not None and banned[y]:
                        continue
                    if banedge is not None and ((x==banedge[0] and y==banedge[1]) or (x==banedge[1] and y==banedge[0])):
                        continue
                    dist[y]=dx
                    dq.append(y)
        return dist
    dS=bfs(S); dT=bfs(T)
    d=dS[T]
    INF=float('inf')
    # layer condition
    cnt=[0]*(d+1)
    layer_vert=[0]*(d+1)
    for v in range(1,n+1):
        if dS[v]+dT[v]==d:
            cnt[dS[v]]+=1
            layer_vert[dS[v]]=v
    for i in range(1,d):
        if cnt[i]>=2:
            print(2*d); return
    best=INF
    # parity walk
    pd=[[-1,-1] for _ in range(n+1)]
    pd[S][0]=0
    dq=deque([(S,0)])
    while dq:
        x,p=dq.popleft()
        dx=pd[x][p]+1
        q=1-p
        for y in adj[x]:
            if pd[y][q]<0:
                pd[y][q]=dx
                dq.append((y,q))
    w=pd[T][(d+1)%2]
    if w>=0 and w<=d+1:
        print(2*d+1); return
    # cycle via H
    banned=[False]*(n+1)
    for i in range(1,d):
        banned[layer_vert[i]]=True
    if d==1:
        dh=bfs(S,None,(S,T))
    else:
        dh=bfs(S,banned)
    if dh[T]>=0:
        best=min(best,d+dh[T])
    # branch
    for v in range(1,n+1):
        if len(adj[v])>=3:
            ca=0;cb=0;cab=0
            sv=dS[v]-1; tv=dT[v]-1
            for y in adj[v]:
                a=dS[y]==sv; b=dT[y]==tv
                if a: ca+=1
                if b: cb+=1
                if a and b: cab+=1
            base=2*(dS[v]+dT[v])
            if ca>=1 and cb>=1 and ca+cb-cab>=2:
