from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    n, m, S, T = int(data[0]), int(data[1]), int(data[2]), int(data[3])
    adj = [[] for _ in range(n + 1)]
    idx = 4
    for _ in range(m):
        u = int(data[idx]); v = int(data[idx + 1]); idx += 2
        adj[u].append(v); adj[v].append(u)
    INF = float('inf')

    def bfs(src, banned):
        dist = [-1] * (n + 1)
        dist[src] = 0
        if banned:
            dist[banned] = -2
        dq = deque([src])
        while dq:
            u = dq.popleft()
            du = dist[u] + 1
            for w in adj[u]:
                if dist[w] == -1:
                    dist[w] = du
                    dq.append(w)
        if banned:
            dist[banned] = -1
        return dist

    dS = bfs(S, 0)
    dT = bfs(T, 0)
    d = dS[T]

    # vertices on shortest paths
    cnt = [0] * (d + 1)
    onP = [False] * (n + 1)
    for v in range(1, n + 1):
        if dS[v] + dT[v] == d:
            onP[v] = True
            cnt[dS[v]] += 1
    for k in range(1, d):
        if cnt[k] >= 2:
            print(2 * d)
            return

    best = INF

    # interior vertex with off-P neighbor
    for v in range(1, n + 1):
        if onP[v] and v != S and v != T:
            for w in adj[v]:
                if not onP[w]:
                    best = 2 * d + 2
                    break
            if best == 2 * d + 2:
                break

    # Type1
    d1 = bfs(T, S)  # G - S
    d2 = bfs(S, T)  # G - T
    for x in range(1, n + 1):
        if not onP[x] and d1[x] >= 0 and d2[x] >= 0:
            c = d + d1[x] + d2[x]
            if c < best:
                best = c

    # Type2
    hbest = INF
    for c in range(1, n + 1):
        if len(adj[c]) >= 3:
            h = min(dS[c], dT[c])
            if h < hbest:
                hbest = h
    if hbest < INF:
        c = 2 * d + 4 * hbest + 4
        if c < best:
            best = c

    print(best if best < INF else -1)

main()

