    def lin(seg, init_flag):
        # states: (open, flag)
        L = len(seg)
        cur = {(False, init_flag)}
        for i in range(L):
            nxt = set()
            for (op, fl) in cur:
                if op:
                    nxt.add((False, fl))
                else:
                    if seg[i] == 1:
                        nxt.add((False, True))
                    if i + 1 < L:
                        nxt.add((True, fl))
            cur = nxt
            if not cur:
                return False
        return (False, True) in cur

    # case B: pair (N-1,0) not used
    if lin(a, False):
        print("Yes")
        return
    # case A: pair (N-1,0) used
    if n >= 2:
        seg = a[1:n-1]
        if lin(seg, False):
            print("Yes")
            return
    print("No")

