def main():
    W,H,L,R,D,U = map(int, sys.stdin.read().split())
    M = 998244353
    N = W+H+10
    f = [1]*(N+1)
    for i in range(1,N+1):
        f[i] = f[i-1]*i % M
    inv = [1]*(N+1)
    inv[N] = pow(f[N], M-2, M)
    for i in range(N,0,-1):
        inv[i-1] = inv[i]*i % M
    def C(n,k):
        if k<0 or k>n or n<0: return 0
        return f[n]*inv[k]%M*inv[n-k]%M
    def colsum(i,j1,j2):
        # sum_{j=j1}^{j2} C(i+j,i)
        return (C(i+j2+1,i+1) - C(i+j1,i+1)) % M
    def g(x,y):
        return (C(x+y+2,x+1)-1) % M
    def h(x,y):
        return g(W-x,H-y)
    total = 0
    for x in range(W+1):
        total += colsum(x+1,1,H+1)
    total -= (W+1)*(H+1)
    total %= M
    bad = 0
    for x in range(L,R+1):
        i = W-x+1
        bad += colsum(i, H-U+1, H-D+1)
    bad -= (R-L+1)*(U-D+1)
    bad %= M
    if L>=1:
        for y in range(D,U+1):
            bad += g(L-1,y)*h(L,y)
        bad %= M
    if D>=1:
        for x in range(L,R+1):
            bad += g(x,D-1)*h(x,D)
        bad %= M
    print((total-bad) % M)
