def main():
    data=sys.stdin.read().split()
    n=int(data[0]); s=data[1]
    M=998244353
    def step(mask,y,sv):
        r=0
        for a in (0,1):
            if mask>>a&1:
                xs=(0,1) if sv else (0,)
                for x in xs:
                    c=a+x-y
                    if 0<=c<=1:
                        r|=1<<c
        return r
    start=(1,2)
    idx={start:0}
    order=[start]
    trans={0:[],1:[]}
    q=0
    while q<len(order):
        st=order[q]; q+=1
        for sv in (0,1):
            for y in (-1,0,1,2):
                nt=(step(st[0],y,sv),step(st[1],y,sv))
                if nt==(0,0): continue
                if nt not in idx:
                    idx[nt]=len(order); order.append(nt)
    K=len(order)
    # build transitions
    T={0:[dict() for _ in range(K)],1:[dict() for _ in range(K)]}
    for i,st in enumerate(order):
