import numpy as np

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); s = data[1]
    p = 998244353
    # boolean 2x2 matrix as mask: bit a*2+b
    def mat(pairs):
        m = 0
        for a, b in pairs:
            m |= 1 << (a * 2 + b)
        return m
    def mul(M, L):
        r = 0
        for a in range(2):
            for c in range(2):
                for b in range(2):
                    if (M >> (a*2+b)) & 1 and (L >> (b*2+c)) & 1:
                        r |= 1 << (a*2+c)
                        break
        return r
    A = mat([(0, 1)])
    I = mat([(0, 0), (1, 1)])
    C = mat([(1, 0)])
    E = mat([(0, 0), (0, 1), (1, 1)])
    F = mat([(1, 0), (0, 0), (1, 1)])
    letters0 = [A, I, C]
    letters1 = [A, E, F, C]
    T = []
    for lets in (letters0, letters1):
        Tm = np.zeros((16, 16), dtype=np.int64)
        for st in range(16):
            for l in lets:
                Tm[st, mul(st, l)] += 1
        T.append(Tm)

    def mm(Am, Bm):
        Bl = Bm & 32767
        Bh = Bm >> 15
        return (((Am @ Bh) % p) * 32768 + (Am @ Bl)) % p

    k = 10
    if n >= k:
        Ms = np.eye(16, dtype=np.int64)[None, :, :]
        for L in range(k):
            M0 = mm(Ms, T[0][None, :, :])
            M1 = mm(Ms, T[1][None, :, :])
            Ms = np.stack([M0, M1], axis=1).reshape(-1, 16, 16)
    v = np.zeros(16, dtype=np.int64)
    v[I] = 1
    nb = n // k
    for b in range(nb):
        pat = int(s[b*k:(b+1)*k], 2)
        v = mm(v, Ms[pat])
    for j in range(nb * k, n):
        v = mm(v, T[int(s[j])])
    ans = 0
    for st in range(16):
        if (st & 1) or ((st >> 3) & 1):
            ans = (ans + int(v[st])) % p
    print(ans)

main()

