    for _ in range(t):
        n = int(data[idx]); idx += 1
        A = data[idx]; idx += 1
        B = data[idx]; idx += 1
        xs = [i for i in range(n) if A[i] == 49]
        bs = [i for i in range(n) if B[i] == 49]
        m = len(xs); k = len(bs)
        if k > m:
            out.append("-1")
            continue
        LB = max(abs(bs[0] - xs[0]), abs(xs[-1] - bs[-1]))

        def feasible(q):
            g = 0  # 0-indexed group
            km1 = k - 1
            if km1 == 0:
                return True
            for p in range(m - 1):
                if g < km1:
                    d = bs[g] - xs[p]
                    d2 = bs[g + 1] - xs[p + 1]
                    if d2 < d or (d2 == d and (d & 1) == q):
                        g += 1
                        if g == km1:
                            return True
                else:
                    return True
            return g == km1

        if feasible(LB & 1):
            out.append(str(LB))
        elif feasible((LB + 1) & 1):
            out.append(str(LB + 1))
        else:
            out.append("-1")
