def main():
    data=sys.stdin.buffer.read().split()
    n=int(data[0])
    A=data[1:1+n]; B=data[1+n:1+2*n]; C=list(map(int,data[1+2*n:1+3*n]))
    vals=sorted(set(C)); idx={v:i+1 for i,v in enumerate(vals)}
    m=len(vals)
    # BITs
    dc=[0]*(m+1); ds=[0]*(m+1); uc=[0]*(m+1); us=[0]*(m+1)
    def add(bc,bs,i,v):
        while i<=m:
            bc[i]+=1; bs[i]+=v; i+=i&-i
    def q(bc,bs,i):
        c=0;s=0
        while i>0:
            c+=bc[i]; s+=bs[i]; i-=i&-i
        return c,s
    state={'Dn':0,'Dt':0,'Ds':0,'Di':0,'Un':0,'Ut':0,'Us':0,'Ui':0}
    def addD(x):
        i=idx[x]
        cl,sl=q(dc,ds,i-1)
        g=state['Dn']-cl
        state['Di']+=x*g+sl
        add(dc,ds,i,x); state['Dn']+=1
    def addU(x):
        i=idx[x]
        cl,sl=q(uc,us,i-1)
        g=state['Un']-cl
        state['Ui']+=x*(1+g)+sl
        add(uc,us,i,x); state['Un']+=1
    S=0; ones=[]
    for i in range(n):
        a=A[i]==b'1'; b=B[i]==b'1'
        if a and not b: addD(C[i])
        elif b and not a: addU(C[i])
        elif a and b:
            S+=C[i]; ones.append(C[i])
    def total():
        return (state['Dn']+state['Un'])*S+state['Di']+state['Ui']
    best=total()
    ones.sort(reverse=True)
    for x in ones:
        S-=x
        addD(x); addU(x)
        t=total()
        if t<best: best=t
    print(best)
